-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(3763, { "classic", "forever" }, { deDE = { completion = "Nun gut, {class}... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen." }, enUS = { completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself." } })
apply(3764, { "classic", "forever" }, { deDE = { progress = "Ach ja, die Erde. Der Erzdruide möchte zwanzig Ladungen pro Abenteurer, und zwanzig Ladungen wird er bekommen. Lasst die, die gegen uns konspirieren, auf der Strecke bleiben!", completion = "Ladet Eure wertvolle Fracht hier ab, edler {class}. Es muss eine rechte Bürde gewesen sein... ähnlich der Bürde, die ich als Visionär mit mir herumtrage. Hier ist eine Entlohnung für Eure Arbeit, wie es der Erzdruide höchstpersönlich angewiesen hat.\n\nErzdruide Staghelm möchte erneut mit Euch sprechen, {name}, aber für seine nächste Aufgabe wäre Euch geholfen, wenn Ihr über das Wissen eines Gesellen der Kräuterkunde verfügt. Falls Ihr nicht über dieses Wissen verfügt, werdet Ihr dennoch hilfreich für den Zirkel sein." }, enUS = { progress = "Ah yes, the dirt.  The Arch Druid wants twenty loads per adventurer, and twenty loads he shall get.  Let those who conspire against us fall to the wayside!", completion = "Unload your precious cargo here, noble {class}.  It must have been quite the burden... not unlike the burden I carry being a visionary.  Here is an honorarium for your work, as dictated by the Arch Druid himself.\n\nArch Druid Staghelm wants to speak with you again {name}, but for his next task you will be aided if you have a journeyman's understanding of Herbalism.  If you don't know it though, you will still be able to aid the Circle!" } })
apply(3765, { "classic", "forever" }, { deDE = { completion = "Ah, mein Bruder Argos hat Euch also zu mir geschickt? Ich nehme an, Ihr seid müde von Eurer Reise. Aber wir müssen über vieles sprechen." }, enUS = { completion = "Ah, so my brother, Argos, sent you? I realize you must be weary from your travels. But we have much to talk about." } })
apply(3781, { "classic", "forever" }, { deDE = { progress = "Friede und Klarheit seien mit Euch, Freund. Ihr seid im Auftrag des Erzdruiden höchstpersönlich hier, nicht wahr?", completion = "Ja, dieser Gutschein ist gültig für zwanzig Pakete mit Samenkörnern. Wenn Ihr die verbraucht habt, kein Problem, bei uns gibt es noch mehr. Leider ist es aber recht kostspielig, Tharlendrissamenkörner in großer Zahl zu produzieren. Daher bittet der Zirkel des Cenarius diejenigen, die uns helfen, einen Teil der Kosten auszugleichen.\n\nDiejenigen, die mit Morgenkorn zurückkehren, werden feststellen, dass die Belohnung, die der Erzdruide bietet, die Kosten mehr als wettmacht." }, enUS = { progress = "Peace and serenity be yours, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out, we have more that can be provided.  Unfortunately though, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.\n\nThose who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost." } })
apply(3782, { "classic", "forever" }, { deDE = { progress = "Friede mit dir, Freund. Ihr seid im Auftrag des Erzdruiden höchstpersönlich hier, nicht wahr?", completion = "Ja, dieser Gutschein ist gültig für zwanzig Pakete mit Samenkörnern. Wenn Ihr die Samenkörner verbraucht habt, habe ich noch mehr, die ich Euch verkaufen kann.\n\nLeider ist es aber recht kostspielig, {name}, Tharlendrissamenkörner in großer Zahl zu produzieren. Daher bittet der Zirkel des Cenarius diejenigen, die uns helfen, einen Teil der Kosten auszugleichen. Diejenigen, die mit Morgenkorn zurückkehren, werden feststellen, dass die Belohnung, die der Erzdruide bietet, die Kosten mehr als wettmacht." }, enUS = { progress = "Peace unto you, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out of seeds, I do have more that I am able to sell to you.\n\nUnfortunately {name}, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.  Those who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost." } })
apply(3783, { "classic", "forever" }, { deDE = { progress = "Ich habe hier viel zu tun. Bitte, besorgt mir diese Felle, so schnell Ihr könnt!", completion = "Diese Felle sind perfekt, {name}. Damit haben wir einen guten Anfang!" }, enUS = { progress = "I've got lots to get started on here. Please get me those furs as soon as you can!", completion = "These furs are perfect, {name}. We're off to a great start here!" } })
apply(3784, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt." }, enUS = { completion = "Greetings, {class}; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before." } })
apply(3785, { "classic", "forever" }, { deDE = { progress = "Also, {name}, habt Ihr Morgenkorn für die wichtigen Forschungen des Erzdruiden gezüchtet? Die Arbeit, die er für den Zirkel des Cenarius leistet, ist sehr wichtig und Eure Hilfe wird nicht unbemerkt bleiben!", completion = "Gut gemacht, {name}, ich werde sie dem Erzdruiden geben, wenn er sie benötigt. Nehmt dies in der Zwischenzeit als Zeichen der Wertschätzung des Zirkels des Cenarius.\n\nWir benötigen fortlaufend Morgenkorn; wenn Ihr uns auch weiterhin helfen wollt, dann kehrt bitte zu mir zurück, sobald Ihr weiteres Morgenkorn kultiviert habt." }, enUS = { progress = "Yes {name}, have you grown some morrowgrain for the Arch Druid's important research?  The work he is doing for the Cenarion Circle is very important, and your assistance will not go unnoticed!", completion = "Well done {name}, I will be sure to give these to the Arch Druid himself when he has need of them.  Meanwhile, please accept this as a token of the Cenarion Circle's appreciation.\n\nOur need for morrowgrain is a continuous one; if you wish to continue aiding us, then please return to me when you have cultivated additional morrowgrain for us." } })
apply(3786, { "classic", "forever" }, { deDE = { progress = "Also, {name}, habt Ihr Morgenkorn für die wichtigen Forschungen des Erzdruiden gezüchtet? Die rätselhaften Eigenschaften des Un'Goro Kraters werden dank Eurer Hilfe mit jedem Tag klarer.", completion = "Gut gemacht, {name}, ich werde sie dem Erzdruiden geben, wenn er sie benötigt. Nehmt dies in der Zwischenzeit als Zeichen der Wertschätzung des Zirkels des Cenarius.\n\nWir benötigen im Moment fortlaufend Morgenkorn; wenn Ihr uns auch weiterhin helfen wollt, dann kehrt bitte zu mir zurück, sobald Ihr weiteres kultiviert habt." }, enUS = { progress = "Yes {name}, have you grown some morrowgrain for the Arch Druid's important research?  The mysterious properties of Un'Goro Crater become clearer with each passing day, thanks to the help you are giving us.", completion = "Well done {name}, I will be sure to give these to the Arch Druid himself when he has need of them.  Meanwhile, please accept this as a token of the Cenarion Circle's appreciation.\n\nOur need for morrowgrain, for now, is constant; if you wish to continue aiding us, then please return when you have cultivated more of it." } })
apply(3787, { "classic", "forever" }, { deDE = { completion = "Ich danke Euch für Euer Kommen, müder Reisender! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.\n\nBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren." }, enUS = { completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed." } })
apply(3788, { "classic", "forever" }, { deDE = { completion = "Ich danke Euch für Euer Kommen, müder Reisender! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.\n\nBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren." }, enUS = { completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed." } })
apply(3789, { "classic", "forever" }, { deDE = { completion = "Nun gut, {class}... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen." }, enUS = { completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself." } })
apply(3790, { "classic", "forever" }, { deDE = { completion = "Nun gut, {class}... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen." }, enUS = { completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself." } })
apply(3791, { "classic", "forever" }, { deDE = { progress = "Ich benötige zehn Einheiten Morgenkorn - das sollte genügen, um meine Forschungen zumindest in Gang zu bringen. Zweifellos werde ich etliche davon beim Verfolgen falscher Spuren verbrauchen, aber das liegt in der Natur der Forschung.", completion = "Gah, durch dieses Morgenkorn fühle ich mich... merkwürdig. Was in Elunes Namen will Staghelm mit diesen Dingern?\n\nEgal, nochmals danke für Eure Hilfe. Hier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe. Meine Forschungen zum Thema Morgenkorn werden einige Zeit dauern, und ich werde zweifellos mehr davon benötigen. Wo ich gerade dabei bin: Ich denke, ich könnte die Zeit vielleicht nutzen um herauszufinden, ob Morgenkorn eine brauchbare alchimistische Verwendung hat. Trotzdem fühle ich mich in seiner Umgebung äußerst unwohl." }, enUS = { progress = "I'm looking for ten morrowgrain - that should be enough to at least get my research started.  I'll no doubt burn through a lot of those going down wrong paths, but such is the nature of research.", completion = "Gah, these morrowgrain make me feel... weird.  What in the name of Elune is Staghelm up to with these things?\n\nAnyway, thank you again for your help.  Here's a little something... you know, for the effort.  My research on morrowgrain is going to take a while, and I no doubt am going to need more.  While I'm at it, I suppose I could take the time to see if morrowgrain have some pertinent alchemical uses.  Still, I feel uncomfortable even being around them." } })
apply(3802, { "classic", "forever" }, { deDE = { progress = "Die Statue ragt bedrohlich über Euch auf.", completion = "Der Hammer gleitet sicher an seinen Platz, in greifbarer Nähe des massiven Monuments der Dunkeleisenzwerge. Am Fundament der Statue öffnet sich ein winziges Fach. Darin findet Ihr..." }, enUS = { progress = "The statue looms ominously above you.", completion = "The hammer slides firmly into place, within the grasp of the massive Dark Iron monument. A tiny compartment opens at the base of the statue. Inside you find..." } })
apply(3821, { "classic", "forever" }, { deDE = { completion = "Mein armer Thal'trak.\n\nWir hatten vor, zu meinen Eltern ins Hinterland zu ziehen, sobald unsere Dienstzeit abgeleistet war. Jetzt sind unsere Pläne ruiniert!" }, enUS = { completion = "My poor Thal'trak.\n\nWe were planning on moving in with my mother and father in the Hinterlands after our tours were over. Now those plans are ruined!" } })
apply(3822, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Sha'ni gefunden? Geht es ihr gut?", completion = "<Thal'trak bricht zusammen.>\n\nWir wollten ins Hinterland ziehen. Hat sie Euch das schon erzählt? Das sollte ihre letzte Mission sein.\n\n<Thal'trak schluchzt.>\n\nIch will ihn nicht, {name}. Behaltet ihn, werft ihn weg, es ist mir egal! Der Ring hat keine Bedeutung mehr für mich. Nicht ohne sie ..." }, enUS = { progress = "Did you find Sha'ni? Is she ok?", completion = "<Thal'trak collapses.>\n\nWe were going to move to the Hinterlands. Did she tell you? This was going to be her last mission.\n\n<Thal'trak sobs.>\n\nI don't want it, {name}. Keep it, throw it away, I don't care! The ring means nothing to me now. Not without her..." } })
apply(3823, { "classic", "forever" }, { deDE = { progress = "Es ist nicht annähernd genug Blut auf Eurer Uniform, Soldat!", completion = "Hervorragend, Soldat! Die Orcs und Oger werden von diesem Schlag minutenlang, vielleicht sogar stundenlang gelähmt sein!" }, enUS = { progress = "There is not nearly enough blood on your uniform, soldier!", completion = "Outstanding, soldier! The orcs and ogres will be reeling from this blow for minutes, maybe even hours!" } })
apply(3824, { "classic", "forever" }, { deDE = { progress = "Welch wunderbarer Tag! Seid Ihr mit dem Kopf zurückgekehrt?", completion = "Seht Euch das an, Soldat. Widerlich! Wenn die verbleibenden Feuermagenoger diese fette Visage auf einem Pfahl aufgespießt sehen, der auf der Spitze ihres Berges steht, wird es zu einer Massenhysterie kommen!\n\n<Oralius kichert wild.>" }, enUS = { progress = "Oh glorious day! Have you returned with the head?", completion = "Just look at it, soldier. Disgusting! When the remaining Firegut ogres see this fat mug stuck on a pike sitting at the top of their mountain, mass hysteria will ensue!\n\n<Oralius cackles wildly.>" } })
apply(3825, { "classic", "forever" }, { deDE = { progress = "Und? Habt Ihr von dem Ereignis Bilder gemalt?", completion = "Hervorragende Arbeit, Soldat! Einfach unglaublich! Oh, ich werde dafür die Tapferkeitsmedaille bekommen, äh, ich meine, Ihr werdet fürstlich dafür belohnt werden!" }, enUS = { progress = "So? Did you paint any pictures of the event?", completion = "Outstanding work, soldier! Simply amazing! Oh I'll get the medal of bravery for this, er, I mean you'll be rewarded handsomely for this!" } })
apply(3842, { "classic", "forever" }, { deDE = { progress = "Je länger ich hier bin, desto mehr überkommt mich die Lust, an diesen Rennen teilzunehmen, {name}. Einfach überwältigend...\n\nHabt Ihr die Elixiere schon gefunden? Sobald ich sagen kann, ob das Ei gesund ist oder nicht, gebe ich es Euch zurück, damit Ihr es aufbewahrt, bis es schlüpft.\n\nSagt mir einfach Bescheid.", completion = "Großartig. Die sind perfekt. Gebt mir einen Augenblick, damit ich die Komponenten miteinander vermischen kann, und dann werden wir ja sehen, wie sich dieses Ei einmal machen wird." }, enUS = { progress = "The longer I stay here, the more tempted I am to partake in these races, {name}. Truly boggling...\n\nHave you found the elixirs yet? Once I can tell if the egg is going to be healthy or not, I'll return it to you to hold onto until it's prepared to hatch.\n\nLet me know.", completion = "Wonderful. These will do nicely. Give me a moment to mix together my components and we shall see how well this egg is going to do." } })
apply(3843, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Kann ich Euch mit irgendwas helfen?", completion = "Ja, was haben wir denn hier? So etwas hab ich ja schon seit Ewigkeiten nicht mehr gesehen! Feendrache, wenn ich mich nicht irre... und zwar ein Grimmlingflitzer, wie's aussieht. Ausgezeichnet, ganz ausgezeichnet.\n\nNa, wenn der kleine Kerl hier schlüpfen und mal ein starker und gesunder Flitzer werden soll, dann sollten wir ihm was zu essen beschaffen. Gut, dass Ihr's mir grad noch rechtzeitig gebracht habt." }, enUS = { progress = "Greetin's, {name}. How can I be of service to ya?", completion = "Well, well, well... I haven't seen one of these in a dragon's age. Faerie dragon, if I'm not mistaken... looks to be of the sprite darter variety. Excellent, excellent indeed.\n\nWell, if this little fella's gonna hatch and live to be strong and healthy, then we should get some food for it. Good ya got it to me in time." } })
apply(3844, { "classic", "forever" }, { deDE = { completion = "Am Grund des Tümpels liegt ein durchnässtes Bündel." }, enUS = { completion = "A water-logged pack rests at the bottom of the pond." } })
apply(3845, { "classic", "forever" }, { deDE = { progress = "Hallo, Ihr da! Euch hab ich doch schon mal gesehen... Oder nicht?", completion = "Oh... Ja, die Sachen kommen mir bekannt vor... irgendwie schon..." }, enUS = { progress = "Hi there. I've seen you before... Haven't I?", completion = "Oh... Yes, these things do look familiar... well, kind of..." } })
apply(3861, { "classic", "forever" }, { deDE = { progress = "Das Huhn starrt Euch mit dunklen, kalten Augen an. Hungrig wartet es auf Euch.\n\n\"GAGGAAACK!\n\nGack... gack... gack.\"", completion = "GAGGACK!!!\n\nDas Huhn beginnt gierig, das Futter aufzupicken, das Ihr ihm hingestreut habt.\n\nNach einer kurzen Weile sieht es sich überrascht um. Dann trippelt es unruhig vor und zurück. Ob dieses Huhn vielleicht gleich ein Ei legt? Vielleicht solltet Ihr besser einmal darunter nachsehen." }, enUS = { progress = "The chicken stares at you with dark, cold eyes. It waits for you hungrily.\n\n\"BACAAAW!\n\nCluck...cluck...cluck.\"", completion = "\"BACAW!!!\"\n\nThe chicken starts to gobble up the feed you put down.\n\nAfter a moment, the chicken looks around, startled. It uncomfortably shuffles back and forth. Is this chicken pregnant? You think you better check underneath it." } })
apply(3881, { "classic", "forever" }, { deDE = { progress = "Wenn wir auch nur die geringste Chance haben wollen, hier lebendig rauszukommen, dann brauchen wir unsere große Kiste mit Nahrungsmitteln. Und zumindest einen Teil unserer Forscherausrüstung zurückzubekommen, das wäre ein Segen in diesem Meer des Elends.", completion = "Ihr habt ja sogar beides wiederbeschafft: unsere Nahrungsmittel UND unsere Forscherausrüstung! Ihr habt nicht nur die Expedition gerettet, sondern auch unser aller Leben. Mein Team und ich können Euch gar nicht genug danken; Euretwegen können wir jetzt wenigstens eine Zeit lang weitermachen.\n\nWir haben zwar nicht viel, aber ich werde Euch bestimmt nicht auf dem Trockenen sitzen lassen als Dank für die unschätzbare Hilfe, die Ihr uns erwiesen habt! Danke, {name}, Ihr habt jetzt einen Freund bei Marshals Expeditionen!" }, enUS = { progress = "If we're going to have any chance of getting out of here alive, we'll need our big crate of foodstuffs.  Also, getting at least some of our research equipment back would be a blessing in a sea of misery.", completion = "You got both our foodstuff AND our research equipment back!  You've not only saved the expedition, you've also saved our lives.  I and the rest of my team can't thank you enough; we just might make it here for a while now thanks to you.\n\nWhile we don't have much, I'm certainly not going to leave you high and dry for the invaluable help you've given us.  Thank you, {name} - you've got a friend in Marshal Expeditions!" } })
apply(3882, { "classic", "forever" }, { deDE = { progress = "Ihr könnt von mir denken, was Ihr wollt, aber denen ist es doch völlig egal, ob die Knochen, die sie zum Erforschen bekommen, von uralten Stegodons und Dimetrodons stammen oder von den Viechern, die uns beinahe zum Frühstück verspeist hätten, als wir gerade unser Lager aufschlugen. Ich wäre schon glücklich, wenn wir hier lebend rauskämen...", completion = "Wunderbar, das sollte funktionieren. Und jetzt, wenn Ihr erlaubt...\n\nDANKE, DASS IHR ALL DIESE KNOCHEN FÜR UNS AUSGEGRABEN HABT, OHNE DEN HIER LEBENDEN TIEREN SCHADEN ZUZUFÜGEN!\n\nOb das wirklich so war oder nicht, das will ich gar nicht wissen. Belassen wir es dabei, in Ordnung? Hier - vielleicht hilft Euch das, über die ganze Angelegenheit Euren Mund zu halten. Jedes Mittel ist recht, wenn wir nur lebendig hier rauskommen, sage ich!" }, enUS = { progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ones from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!" } })
apply(3883, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Probe des Gorishischwarmbaus, damit ich sie untersuchen kann, {name}?", completion = "Ja, die ist prima. Ihr wart mir eine große Hilfe... Ich wünschte, ich könnte Euch mehr geben als das hier, aber wenn man mitten in einer primitiven Gegend festsitzt, dann schränkt einen das in seinen Möglichkeiten schon ein bisschen ein. Eines ist jedoch sicher: Die Forschungsarbeit, die hier geleistet wird, wäre ohne Eure Hilfe nicht möglich!" }, enUS = { progress = "Do you have the sample of the Gorishi hive for me to study, {name}?", completion = "Yes, this will do nicely.  You've been a great help... I wish I could give you more than this, but being virtually stranded in the middle of a savage land does limit what I can and cannot give.  Rest assured though - the research done here would not have been possible without your assistance!" } })
apply(3884, { "classic", "forever" }, { deDE = { progress = "Hallo! Meine Begleiter und ich sind glücklich, endlich wieder andere lebende Wesen hier zu sehen und nicht nur diese übergroßen wilden Bestien! Was führt Euch in den Un'Goro Krater?", completion = "Na sieh mal einer an - mein Tagebuch! Ich hatte schon gedacht, es sei verloren, genauso wie fast alles andere, das wir zum Un'Goro mitgenommen hatten. Vielen herzlichen Dank, dass Ihr es mir zurückgebracht habt!" }, enUS = { progress = "Hello there!  I and my companions are happy to see some living beings here other than overgrown savage beasts!  What brings you into the Un'Goro Crater?", completion = "Well look at this - my journal!  I thought it was lost, much like almost everything else we brought into Un'Goro.  I thank you kindly for returning this to me!" } })
apply(3901, { "classic", "forever" }, { deDE = { completion = "Ich bin fertig mit Euch, {name}. Ihr habt bewiesen, dass Ihr der Freiheit, die Euch gegeben wurde, würdig seid. Viele werden Euch verachten für das, was aus Euch geworden ist. Doch wisset, was auch immer sie versuchen uns anzutun, wir sind frei und werden uns nicht wieder fesseln lassen.\n\nNehmt dies und macht Euch auf den Weg. Es liegt viel Arbeit vor Euch, {class}." }, enUS = { completion = "I am finished with you, {name} - you have shown yourself to be worthy of the freedom that you have been given.  Many will stand against you for what you have become, but know that no matter what they may try to do against us, we are free and will not be shackled again.\n\nTake these and be on your way.  You have much to accomplish, {class}." } })
apply(3902, { "classic", "forever" }, { deDE = { progress = "Habt Ihr ein paar nützliche Gegenstände für uns aufstöbern können? Es ist keine Schande, das wieder zu verwenden, was von anderen fortgeworfen wurde. Niemand wird uns irgendwelche Almosen geben - wir Verlassenen werden für uns selbst sorgen!", completion = "Gute Arbeit, {name}, ich wusste, dass Ihr nicht völlig nutzlos seid. Hier, nehmt Euch einen der besseren Gegenstände, die ich aus dem herausgefischt habe, was bisher bereits gesammelt wurde." }, enUS = { progress = "Have you managed to scavenge up some useful items for us?  There is no shame in reusing that which has been tossed aside.  No one is going to give us any handouts - we Forsaken will fend for ourselves!", completion = "Great work {name}, I knew you weren't useless.  Here - have one of the better items I've found out of the lots that have been collected so far." } })
apply(3903, { "classic", "forever" }, { deDE = { completion = "Ach, Deputy Willem hat Euch also gesagt, Ihr sollt mit mir reden, ja? Er ist ein tapferer Kerl und immer bereit, mir zu helfen, aber seine Pflichten halten ihn in der Abtei von Nordhain fest und ich fürchte, das Problem, das ich heute habe, ist etwas zu groß für ihn.\n\nVielleicht könnt Ihr mir helfen?" }, enUS = { completion = "Oh, Deputy Willem told you to speak with me?  He's a brave man and always willing to help, but his duties keep him stuck at Northshire Abbey and I'm afraid the problem I have today is beyond him.\n\nPerhaps you can help me?" } })
apply(3904, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Ernte, {name}?", completion = "Oh, danke, {name}! Ihr habt meine Ernte gerettet! Und ich hoffe, Ihr habt einigen von diesen Defias gezeigt, dass sie hier nicht so einfach Ärger machen können.\n\nWir sind zur Zeit zwar knapp an Wachen, aber glücklicherweise haben wir Helden wie Euch, die uns beschützen!" }, enUS = { progress = "Do you have my harvest, {name}?", completion = "Oh thank you, {name}!  You saved my harvest!  And I hope you showed a few of those Defias that they can't cause trouble around here.\n\nWe might be short on guards these days, but we're lucky to have heroes like you to protect us!" } })
apply(3905, { "classic", "forever" }, { deDE = { progress = "Ihr seht so frohgemut aus! Kommt! Setzt Euch und trinkt etwas!", completion = "Dann zeigt mal her...\n\nMeine Güte! Millys Trauben sind gerettet! Als sie mir erzählte, dass Briganten ihren Weinberg überfallen haben, wäre ich fast verzweifelt, doch ich habe den Glauben an das Licht nicht verloren!\n\nUnd dank Eures Heldenmutes haben wir jetzt Trauben, um neuen Wein herstellen zu können! Möge das Licht Euch segnen und über Euch wachen, {name}!" }, enUS = { progress = "You look to be in fine spirits!  Come!  Have a seat, and have a drink!", completion = "Let's see here...\n\nOh my!  Milly's grapes have been saved!  When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!\n\nAnd through your bravery,  we now have grapes for more wine!  May the Light bless you, {name}, and keep you safe!" } })
apply(3906, { "classic", "forever" }, { deDE = { progress = "Die Elemente befinden sich noch immer in einem Zustand der Unordnung, {name}.", completion = "Das kann nicht sein... es darf nicht sein. Die Vernichtung Pyrons hat lediglich einen Schleier gelüftet. In den Tiefen von Blackrock befindet sich eine noch weit heimtückischere Quelle der Verderbnis." }, enUS = { progress = "The elements are still in disarray, {name}.", completion = "This cannot be... it must not be. The destruction of Pyron has merely lifted a veil. Within the depths of Blackrock is a much more insidious source of corruption." } })
apply(3907, { "classic", "forever" }, { deDE = { progress = "Bald schon werden die Flammen dieses Land überwältigen. Sputet Euch, {name}!", completion = "<Thunderheart umklammert die Schrifttafel von Kurniya.>\n\nRagnaros... hier...\n\nDie Ältesten hatten Recht, die vom Blackrock ausgehende Verderbnis zu fürchten. Ein General der Alten Götter! IN UNSERER WELT! Wir müssen unsere Position hier in Kargath völlig neu überdenken. Wir müssen entscheiden, ob wir bleiben und kämpfen oder ob wir aus Furcht vor einer neuen Teilung flüchten.\n\nHütet Euch vor jeder weiteren Erforschung des Blackrocks, {name}. Ein Übel, das viel größer ist als alles, was in dieser Welt existiert, haust dort unten in den feurigen Tiefen." }, enUS = { progress = "The flames will soon overtake these lands. Make haste, {name}!", completion = "<Thunderheart clutches the Tablet of Kurniya.>\n\nRagnaros... here...\n\nThe elders were right to fear the corruption emanating from Blackrock Mountain. A general of the Old Gods! IN OUR WORLD! We must reassess our position here in Kargath. We must decide on whether we stay and fight or run for fear of a new sundering.\n\nBe wary of any further exploration in Blackrock Mountain, {name}. A far greater evil than anything that exists in this world resides in those fiery depths." } })
apply(3908, { "classic", "forever" }, { deDE = { progress = "Sieh an... Hat Linken mir also doch endlich sein Schwert geschickt.", completion = "Aber natürlich kann ich dieses Schwert aushärten. Und während ich arbeite, könnt Ihr mir erklären, warum Linken so lange gebraucht hat, um mir das Schwert zukommen zu lassen. Normalerweise ist er nicht so vergesslich..." }, enUS = { progress = "My, my... So Linken did finally get around to sending me his sword.", completion = "Well, of course I can temper this sword. While I'm working, you can explain what took Linken so long to get this to me. He's not usually one to forget things..." } })
apply(3909, { "classic", "forever" }, { deDE = { progress = "Schon zurück?", completion = "Eine Phiole davon brauche ich, um sicherzugehen, dass es wirklich das richtige Elixier ist... Ja... Genau das wollte ich." }, enUS = { progress = "Back already?", completion = "I'll need one vial to make sure that this is truly the elixir... Yes... This is the stuff." } })
apply(3913, { "classic", "forever" }, { deDE = { progress = "Das muss der Grabstein sein, von dem Gaeriyan sprach...", completion = "Ihr drückt fest gegen den Stein und er rutscht zur Seite. Darunter wird eine kleine Vertiefung sichtbar.\n\nAls Ihr Linkens Schwert in die Vertiefung legt, stellt Ihr fest, dass es haargenau hineinpasst..." }, enUS = { progress = "This must be the gravestone that Gaeriyan mentioned...", completion = "You push on the stone firmly, and it slides away, revealing a small depression underneath it.\n\nPlacing Linken's Sword into the depression, you realize that it fits perfectly..." } })
apply(3914, { "classic", "forever" }, { deDE = { progress = "Oh! An Euch erinnere ich mich! Ihr seid... Nein, sagt es mir nicht!", completion = "Mein Schwert... Es ist vollendet!\n\nWenn ich mich jetzt doch nur noch daran erinnern könnte, warum ich es brauche...\n\nHier, lasst mich Euch wenigstens für Eure Arbeit bezahlen." }, enUS = { progress = "Oh! I remember you! You are... No, don't tell me!", completion = "My sword... It's finished!\n\nNow, if only I could remember why I needed this...\n\nHere, let me at least pay you for your work." } })
apply(3921, { "classic", "forever" }, { deDE = { progress = "Ich bin gerade sehr beschäftigt, {class}. Wenn Ihr also nichts für mich habt, dann solltet Ihr am besten einfach wieder gehen...", completion = "Oh, was haben wir denn hier? Ein Samophlang, sagt Ihr? Was ist ein Samophlang?\n\nAh, jetzt schaut doch nur, es bewegt sich, wenn man es anfasst. Und im Inneren ist das Geräusch eines komplizierten Getriebes. Oh Mann! Ich will das Ding unbedingt reparieren und sehen, was es tut, Ihr nicht?" }, enUS = { progress = "I'm very busy with my work, {class}.  Unless you have something for me, it'd be best if you moved along...", completion = "Oh, what's this?  A samophlange, you say?  What's a samophlange??\n\nAh... but look at the way it moves when you handle it.  And there's the sound of intricate gears inside.  Oh my!  I want to fix it and see what it does, don't you??" } })
apply(3922, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Nugget-Patronen, {name}? Ständig muss ich mir dieses Samophlang ansehen - ich kann es gar nicht erwarten, endlich daran herumzubasteln.", completion = "Prima, Ihr habt sie! Jetzt kann ich mich endlich an die Arbeit machen..." }, enUS = { progress = "Do you have the nugget slugs, {name}?  I've been eyeing this Samophlange and I can't wait to tinker with it.", completion = "Great, you got them!  Now I can get to work..." } })
apply(3923, { "classic", "forever" }, { deDE = { progress = "Passt auf Euren Kopf auf! Ich will nicht, dass er meiner Arbeit in die Quere kommt!", completion = "Was ist denn das? Aber das ist doch ein Samophlang! Wo habt Ihr das denn her? Habt Ihr etwa in der Anlage der Venture Company im Brachland herumgeschnüffelt?\n\nDann seid Ihr entweder sehr mutig oder sehr dumm." }, enUS = { progress = "Mind your head!  I don't want it to get in the way of my work!", completion = "What's this?  Why, it's a samophlange!  Where did you get this thing?  Have you been poking around the Venture Company holdings in the Barrens?\n\nYou must be very brave, or very stupid." } })
apply(3924, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Handbuch?", completion = "Ihr habt das Handbuch! Ich kann es kaum erwarten, es zu lesen und herauszufinden, wie man das Samophlang reparieren kann! Ich habe mit Sputtervale in Ratchet gesprochen - er möchte Euch für Eure Hilfe danken und Euch für Eure Mühe belohnen.\n\nIch möchte Euch ebenfalls danken - und falls es mir gelingt, dieses Ding hier jemals zu reparieren, lasse ich es Euch wissen ..." }, enUS = { progress = "Do you have the manual?", completion = "You got the manual!  I can't wait to read it and find out how to fix the Samophlange!  I spoke with Sputtervalve in Ratchet--he wanted to thank you for your help, and wanted to reward your efforts.\n\nI want to thank you too, and if I ever get this thing fixed I'll let you know..." } })
apply(3941, { "classic", "forever" }, { deDE = { completion = "Bleibt mal einen Moment da, wo Ihr seid... Ich probiere gerade eine neue Kristallkombination aus..." }, enUS = { completion = "Stay where you are for just a moment... I am testing out a new combination of crystals..." } })
apply(3942, { "classic", "forever" }, { deDE = { completion = "Hallo, {class}. Kann ich Euch irgendwie helfen?" }, enUS = { completion = "Hello, {class}. Is there something I can help you with?" } })
apply(3961, { "classic", "forever" }, { deDE = { progress = "Ach, hallo, {name}!", completion = "Konnte J. D. Euch helfen?" }, enUS = { progress = "Hi, again, {name}!", completion = "Did J.D. help you at all?" } })
apply(3962, { "classic", "forever" }, { deDE = { progress = "Hinter der Aura, die er mit Hilfe der Goldenen Flamme um sich herum erzeugt hat, ist Sturmflamme fast unbesiegbar. Nur Ihr habt die Macht, diese Aura mit dem Silbertotem von Aquementas zu entfernen.", completion = "Ich danke Euch, {name}.\n\nDie Goldene Flamme wird jetzt in meine Heimat zurückgebracht, wo sie beschützt werden wird, damit sie niemals wieder für das Böse eingesetzt werden kann.\n\nDa Ihr so viel für mich getan habt, möchte ich, dass Ihr dies nehmt... Sucht Euch aus, was immer Ihr wollt. Ohne Euch wüsste ich noch immer nicht, wer ich eigentlich bin!" }, enUS = { progress = "Blazerunner is almost invincible behind the aura he has created by using the Golden Flame. Only you have the power to remove it with the Silver Totem of Aquementas.", completion = "Thank you, {name}.\n\nThe Golden Flame will now be returned back to my homeland, where it may be protected, never again to be used for evil.\n\nWithout you, I'd still have no idea who I am! Since you did so much for me, I'd like you to have something special...\n\nTake any one you want!" } })
apply(3981, { "classic", "forever" }, { deDE = { completion = "Wir haben nicht viel Zeit. Hört gut zu, {race}. Was ich Euch zu sagen habe, ist vertraulich und nur für Eure Ohren bestimmt." }, enUS = { completion = "We haven't got much time. Listen carefully, {race}. What I have to tell you is classified and for your ears only." } })
apply(3982, { "classic", "forever" }, { deDE = { progress = "Verteidigt Euch, Dummkopf!", completion = "Das war knapp. Sie wissen jetzt, dass Ihr hier seid... bestimmt kommen bald mehr von ihnen." }, enUS = { progress = "Defend yourself, fool!", completion = "That was a close call. They have been alerted to your presence... more will surely come." } })
apply(4001, { "classic", "forever" }, { deDE = { progress = "Was führt Euch auf diesen geheiligten Boden?", completion = "Dies ist eine Chance für die Horde, das politische Klima in unserer vom Krieg zerrissenen Welt für immer zu verändern. Hört gut zu, {name}.\n\nEinen Fehlschlag dieser Mission werde ich nicht akzeptieren." }, enUS = { progress = "What brings you to these hallowed grounds?", completion = "This is a chance for the Horde to change the political climate of our war torn world forever. Listen carefully, {name}.\n\nFailure of this mission is not an option." } })
apply(4002, { "classic", "forever" }, { deDE = { completion = "Jetzt könnt Ihr nicht mehr zurück, {name}." }, enUS = { completion = "There is no going back beyond this point, {name}." } })
apply(4003, { "classic", "forever" }, { deDE = { completion = "Was habt Ihr getan!!!" }, enUS = { completion = "What have you done!" } })
apply(4004, { "classic", "forever" }, { deDE = { completion = "<Thrall ist bestürzt über die Informationen, die Ihr ihm präsentiert habt.>\n\nJetzt dräut eine neue Bedrohung am Horizont. Da Magnis Jahre sich dem Ende neigen, wird der Weg für diesen ungeborenen Dunkeleisenzwerg geöffnet, um Herrscher von Ironforge zu werden.\n\nIhr habt erreicht, worum ich Euch gebeten habe, und dafür sollt Ihr belohnt werden.\n\nVerlasst mich nun, {name}. Ich muss mich mit Sylvanas und Cairne beraten." }, enUS = { completion = "<Thrall is taken aback by the information you have presented to him.>\n\nA new threat now looms on the horizon. As Magni's years dwindle down, the way shall be opened for this unborn Dark Iron to become ruler of Ironforge.\n\nYou have accomplished what I asked of you and for that, you shall be rewarded.\n\nNow leave me, {name}! I must confer with Sylvanas and Cairne." } })
apply(4005, { "classic", "forever" }, { deDE = { progress = "Ihr seid also zurück, wie? Hmmm... Lasst mich das mal sehen, {name}.", completion = "Sturmflamme, sagt Ihr...\n\nJa, ich weiß, dass sich ein starker Elementar im verkohlten Zentrum des Kraters aufhält. Wir halten uns einfach alle davon fern, denn noch niemand war in der Lage, die mächtige Aura zu durchdringen, die ihn umgibt. Viele schon wurden von den felsigen Pfaden auf den Grund des Kraters hinabgestürzt, als sie versuchten, sich ihm zu stellen." }, enUS = { progress = "So you're back, eh? Hmm... Let me take a look at that, {name}.", completion = "Blazerunner, you say...\n\nYes, I am aware that a strong elemental resides in the charred center of the crater. We all just keep our distance; none have been able to penetrate the powerful aura that surrounds him. Many have been pushed from the rocky paths onto the ground below when trying to face him." } })
apply(4021, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Flagge?", completion = "Ihr habt es geschafft! Ihr habt die Kolkar besiegt!\n\nIch werde dafür sorgen, dass Thrall von Euren Taten hier erfährt, {name}.\n\nSchreitet erhobenen Hauptes dahin. Ihr und die Horde könnt stolz auf Euch sein." }, enUS = { progress = "Do you have the banner?", completion = "You have done it!  You have defeated the Kolkar!\n\nI will be sure Thrall receives word of your actions here, {name}.\n\nStand tall.  You do yourself, and the Horde, proud." } })
apply(4023, { "classic", "forever" }, { deDE = { progress = "<Cyrus' Augen beginnen zu glühen.>", completion = "<Cyrus untersucht die Drachenhaut.>\n\nDamit beweist Ihr, dass Ihr nicht völlig nutzlos seid, sterbliches Wesen." }, enUS = { progress = "<Cyrus's eyes form two blazing spheres.>", completion = "<Cyrus examines the molt.>\n\nYou have proven that you are not entirely useless, mortal." } })
apply(4024, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Riesen niedergestreckt?", completion = "<Cyrus reißt Euch die feurige Essenz aus der Hand.>\n\nJA!\n\nNehmt Euren Lohn und hebt Euch hinfort! Geht mir unverzüglich aus den Augen!" }, enUS = { progress = "Has the giant been felled?", completion = "<Cyrus snatches the fiery essence from your hands.>\n\nYES!\n\nTake your prize and be gone. Leave my sight at once!" } })
apply(4061, { "classic", "forever" }, { deDE = { progress = "Nehmt diese Aufgabe nicht zu leicht, {name}!", completion = "<Theodora legt die Fragmente vor sich hin.>\n\n<Theodora untersucht die Fragmente sorgfältig mit einem riesigen Monokel.>\n\nInteressant. In die strukturelle Basis jedes dieser Fragmente sind... Initialen eingeätzt." }, enUS = { progress = "Do not take this task lightly, {name}!", completion = "<Theodora lays the fragments out before her.>\n\n<Theodora carefully examines the fragments with an enormous monocle.>\n\nInteresting. Etched into the structural foundation of each of these fragments are... initials." } })
apply(4062, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr denn da, {race}?", completion = "<Lotwil erbleicht.>\n\nIch... Ich kenne diese Markierungen." }, enUS = { progress = "What have you got there, {race}?", completion = "<Lotwil's face turns white.>\n\nI... I know these markings." } })
apply(4063, { "classic", "forever" }, { deDE = { progress = "War er es? War er wirklich am Leben?", completion = "Was ist das? Dieser Kopf besteht nicht aus Fleisch und Blut! Es muss eine Schöpfung der Dunkeleisenzwerge sein: ein Schatten Argelmachs - NOCH EINE Maschine! Ich fürchte, Eure Vernichtung Argelmachs wird nicht von Dauer sein und bald wird eine weitere Kopie seinen Platz einnehmen." }, enUS = { progress = "Was it him? Was he really alive?", completion = "What is this?!? This head is not flesh. This is some sort of dark iron creation: A shadow of Argelmach - ANOTHER machine! I suspect that your destruction of Argelmach will be short lived as another shall rise to take 'its' place soon." } })
apply(4081, { "classic", "forever" }, { deDE = { completion = "Dieser erste Schlag sollte Zornesschmied schon ein bisschen die Laune vermiesen. Und jetzt, bewegt Euch, Soldat. Ich muss arbeiten, Schlachten planen, Feinde vernichten!\n\nSchaut Euch die Plakate an, wenn Ihr noch etwas tun wollt." }, enUS = { completion = "This first strike should put a crease in Angerforge's pants. Now, move along soldier. I have work to complete, battles to plan, enemies to crush!\n\nCheck the wanted signs for more work." } })
apply(4082, { "classic", "forever" }, { deDE = { completion = "Ganz zweifellos ist der Zornesschmied jetzt... wütend. Kommt wieder zu mir, wenn Ihr einen dritten Tribut erhaltet, dann können wir mit der Operation 'Tod dem Zornesschmied' beginnen. Ich kann nicht darüber sprechen, was das im Detail bedeutet, aber seid gewiss: jemand wird sterben." }, enUS = { completion = "Angerforge is undoubtedly... angry. Return to me when you receive a third tribute and we shall proceed with Operation: Death to Angerforge. I cannot go into any detail of what this entails, but rest assured, it involves somebody dying." } })
apply(4084, { "classic", "forever" }, { deDE = { progress = "Ich kann Euch mehr über die Macht sagen, die Ihr benötigt, um Sturmflamme zu besiegen, doch zunächst müsst Ihr die Dinge besorgen, die ich brauche.", completion = "Nun gut, {name}. Wie ich sehe, ist es Euch ernst damit, Eurem Freund zu helfen." }, enUS = { progress = "I can tell you more of the power required to defeat Blazerunner, but first, you need to gather the things I require.", completion = "Very well, {name}. I can see you are serious about helping your friend." } })
apply(4101, { "classic", "forever" }, { deDE = { progress = "Ich weiß, dass der Teufelswald leidet, {name}, denn ich leide mit ihm! Doch ich muss standhaft bleiben; fiele mein Wissen in die falschen Hände, dann wäre dies eine Katastrophe für den ganzen Teufelswald.\n\nBringt mir das Blutharz der getöteten Wucherborkenelementare, dann vertraue ich Euch genug, um mir von Euch dabei helfen zu lassen, ein Mittel gegen die Verderbnis herzustellen.", completion = "Mit dem Blutharz werden wir einen Weg finden, die Verderbnis hier im Teufelswald zu besiegen. Ihr habt mir bewiesen, dass Ihr bereit seid, alles zu tun, was notwendig ist, um dem Zirkel des Cenarius zu helfen. Ich vertraue Euch jetzt.\n\nEs mag Euch seltsam erscheinen, dass Ihr Euch mir gegenüber durch die Tötung der Elementare beweisen musstet, doch die Rettung des Lebens von unzähligen intelligenten Wesen rechtfertigt die Mittel, die wir ergriffen haben. Jetzt können wir uns auf die Bewahrung des Lebens konzentrieren... mit den Salben, die ich herzustellen weiß.\n\n{name}, endlich ist die Zeit gekommen, den Teufelswald zu säubern." }, enUS = { progress = "I know Felwood suffers, {name} - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.\n\nBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.", completion = "This blood amber will be used to find a means of defeating the corruption present in Felwood.  You've proven to me that you're willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.\n\nIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.\n\n{name}, the time has come to cleanse Felwood." } })
apply(4102, { "classic", "forever" }, { deDE = { progress = "Ich weiß, dass der Teufelswald leidet, {name}, denn ich leide mit ihm! Doch ich muss standhaft bleiben; fiele mein Wissen in die falschen Hände, dann wäre dies eine Katastrophe für den ganzen Teufelswald.\n\nBringt mir das Blutharz der getöteten Wucherborkenelementare, dann vertraue ich Euch genug, um mir von Euch dabei helfen zu lassen, ein Mittel gegen die Verderbnis herzustellen.", completion = "Mit dem Blutharz werden wir einen Weg finden, die Verderbnis hier im Teufelswald zu besiegen. Ihr habt mir bewiesen, dass Ihr bereit seid, alles zu tun, was notwendig ist, um dem Zirkel des Cenarius zu helfen. Ich vertraue Euch jetzt.\n\nEs mag Euch seltsam erscheinen, dass Ihr Euch mir gegenüber durch die Tötung der Elementare beweisen musstet, doch die Rettung des Lebens von unzähligen intelligenten Wesen rechtfertigt die Mittel, die wir ergriffen haben. Jetzt können wir uns auf die Bewahrung des Lebens konzentrieren... mit den Salben, die ich herzustellen weiß.\n\n{name}, endlich ist die Zeit gekommen, den Teufelswald zu säubern." }, enUS = { progress = "I know Felwood suffers, {name} - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.\n\nBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.", completion = "This blood amber will be used to find a means of defeating the corruption present in Felwood.  You've proven to me that you're willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.\n\nIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.\n\n{name}, the time has come to cleanse Felwood." } })
apply(4120, { "classic", "forever" }, { deDE = { completion = "Nach Euren Beschreibungen klingt es, als würden die Kreaturen eine gedankenlose Wildheit an den Tag legen...\n\nBleibt wachsam, {name}! Es könnte in Eurem Interesse sein, mehr über diese Verderbnis zu erfahren. Kennt immer Euren Feind." }, enUS = { completion = "It sounds from your descriptions as if the creatures show a mindless ferocity...\n\nStay alert, {name}. It would be in your best interest to learn more of the corruption. Always know your enemy." } })
apply(4121, { "classic", "forever" }, { deDE = { progress = "Ich übernehme diesen dreckigen Verräter, {name}.", completion = "Eure Heldentaten sollen nicht unbeachtet bleiben, {name}. Diesen Tribut habt Ihr Euch verdient. Der Kriegsherr wird jetzt mit Euch über die letzte Aufgabe sprechen." }, enUS = { progress = "I will take this traitorous filth, {name}.", completion = "Your heroics will not go unrecognized, {name}. You have earned this tribute. The Warlord will speak with you now in regards to the final mission." } })
apply(4123, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, {name}, nehmt dies als Bezahlung an!" }, enUS = { progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, {name}, take this as payment!" } })
apply(4124, { "classic", "forever" }, { deDE = { completion = "Ich nehme an, Latro hat Euch geschickt. Ich glaube zwar inzwischen, dass es aussichtslos ist, aber ich nehme trotzdem gern jede Hilfe in Anspruch, die Ihr mir geben könnt. Ich muss zugeben... ich werde erleichtert sein, wenn ich diese Sache endlich vergessen kann. Jeden Tag gehe ich in die Wildnis Feralas' hinaus und suche dort nach einem Zeichen von Raschal. Und jeden Abend komme ich heim mit nichts in der Hand als Gnollzähnen und Enttäuschung." }, enUS = { completion = "Latro sent you to me, I presume.  While I think it is a lost cause at this point, I'll take whatever assistance you can offer.  I must admit... I'll be glad once I can put my mind to rest on this matter.  Every day I set out into the wilds of Feralas looking for signs of Raschal, and every night I have come back with nothing to show for my work save gnoll teeth and disappointment." } })
apply(4125, { "classic", "forever" }, { deDE = { completion = "Ihr habt etwas gefunden, das wie ein havariertes Ruderboot aussieht. Durch das etwas schlammige Wasser seht Ihr backbords etliche klaffende Löcher: Das ganze Boot ist fast bis auf sein einfaches hölzernes Grundgerüst zerfetzt. Was auch immer dieses Boot so zugerichtet hat, muss versucht haben, es entzweizubrechen. Steuerbords ist das Boot mit einem kleinen Wappen der Festung Feathermoon bemalt.\n\nIm Matsch am Boden des Bootes seht Ihr etwas metallisch aufblitzen ..." }, enUS = { completion = "You have found what appears to be a wrecked row boat.  Through the slightly muddy water you see gaping holes riddling the port side; the boat is nearly shredded down to its simple wooden frame.  Whatever broke this boat most likely tried to snap it in two.  A small crest of the Feathermoon Stronghold is painted on the starboard side.\n\nIn the mud at the base of the boat, a glint of something metallic catches your eye..." } })
apply(4126, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Rezept, {name}? Ich kann es nicht ertragen, dass diese Dunkeleisenzwerge sich an dem Stammgetränk meiner Familie laben!", completion = "Ihr habt es gefunden! Gut gemacht! Und ich hoffe, dass Ihr diesen Dunkeleisenzwergen und Hurley Pestatem eine ordentliche Abreibung verpasst habt!\n\nDie Donnerbräus stehen Euch jederzeit zu Diensten, {name}! Ihr seid der Held des Tages!" }, enUS = { progress = "Do you have the recipe, {name}?  I can't stand the idea of those Dark Iron dwarves drinking my family's drink!", completion = "You found it!  Well done!  And I hope you gave those Dark Irons, and Hurley Blackbreath, a good thumping!\n\nThe Thunderbrews are at your service, {name}.  You are a hero of heroes!" } })
apply(4127, { "classic", "forever" }, { deDE = { progress = "Ah, da seid Ihr ja wieder, {name}. Ich hoffe, dass Ihr etwas über Raschals Schicksal erfahren habt, so tragisch es auch sein mag.", completion = "Interessant... Ich glaube, das ist Raschals Messer. Ihr sagt, Ihr habt es auf dem Grund des Gewässers zusammen mit seinem Boot entdeckt? Tja, die Entdeckung des Messers allein wird nicht reichen, um Raschals Verschwinden zu erklären. Uns steht jedoch noch eine etwas unkonventionelle Methode zur Verfügung, mit der wir versuchen können, etwas herauszufinden.\n\nHabt Ihr schon mal von Psychometrie gehört?" }, enUS = { progress = "Ah, welcome back {name}.  I hope that you were able to uncover some clue as to Raschal's ultimate fate, as tragic as that may be.", completion = "Interesting... I believe that this is Raschal's knife.  You say you found it at the bottom of the water, along with his boat?  Well, just the knife's discovery might not be enough to connect this to Raschal's disappearance; we do, however, have an unconventional option available to us to try and learn more.\n\nHave you ever heard of psychometry?" } })
apply(4128, { "classic", "forever" }, { deDE = { completion = "Ich bin in der Tat fuchsteufelswild! Man hat mich beraubt! Eines der Rezepte unserer Familie wurde gestohlen! Wie können sie es wagen! Als hätte ich nicht schon Grund genug, die Dunkeleisenzwerge zu hassen! Aber jetzt, oh... jetzt sind sie dran!" }, enUS = { completion = "You're right I'm mad!  I've been robbed!  Robbed of one of our family recipes!  How dare they!  As if I didn't have enough cause to hate the Dark Iron dwarves!  Now, oh... now they're in for it!" } })
apply(4129, { "classic", "forever" }, { deDE = { progress = "Ach nein, also Ginro schickt Euch? Na ja...\n\nPsychometrie zehrt ziemlich an der Psyche... aber meine Verluste beim Kalimdor-Poker auch. Hier in der Festung nennt man mich den 'König der schlechten Karten'. Pech im Spiel... Glück im Umgang mit den Geheimnissen der Natur, könnte man sagen.\n\nWie dem auch sei, natürlich tu ich es. Das könnte genau der Durchbruch sein, den wir brauchen, um etwas über Raschals Schicksal in Erfahrung zu bringen. Wenn Ihr mir das Messer gebt, können wir gleich anfangen.", completion = "Ich danke Euch, {name}.\n\nPsychometrie ist zwar nicht einmal im weitläufigsten Sinn eine exakte Kunst, doch habe ich mich ihrer manchmal bedient, um in Situationen, in denen andere schon längst aufgegeben haben, Erleuchtung zu finden. Ich glaube, wenn ich sie bei dem Messer anwende, das Ihr gefunden habt, könnte uns das einen Hinweis darauf geben, was aus Raschal geworden ist.\n\nEs wird nur einen Moment dauern, aber es ist eine für den Zaubernden nicht gerade angenehme Angelegenheit. Habt Nachsicht mit mir." }, enUS = { progress = "Ginro sent you, eh?\n\nMy psychometric readings are fairly draining on the psyche... but so are my losses at Kalimdor Hold 'Em.  They call me \"King of the Bad Beats\" here in the Stronghold.  Unlucky at cards... lucky at mastering the secrets of nature, I guess.\n\nAnyway, of course I'll do it.  This may be just the breakthrough we need to uncover Raschal's fate.  If you would hand me the knife, we can get started.", completion = "Thank you, {name}.\n\nWhile psychometry isn't an exact art by any stretch of the imagination, I've used it in times past to give insight into situations that others have chalked up to lost causes.  I think using it on the knife you've uncovered will give us a glimpse into what happened to Raschal.\n\nIt will only take a moment to do, but it isn't what I'd call a caster-friendly task.  Bear with me on this." } })
apply(4130, { "classic", "forever" }, { deDE = { completion = "Vielen Dank, dass Ihr mir von Quints Visionen berichtet habt, {name}. Ich werde vielleicht ein bisschen großzügiger bei ihm sein, wenn wir uns das nächste Mal zu einem Kartenspiel zusammensetzen.\n\nRaschal kann in einem Kampf seinen Mann stehen und Gnolle sind nichts, was ihm Sorgen bereiten oder gar in Panik versetzen könnte. Vielleicht ist diese neue Information ja hilfreich für Euch und bringt Euch den Durchbruch, den wir so dringend benötigen." }, enUS = { completion = "Thanks for passing along Quint's visions to me, {name}.  I'll try to remember to be a little easier on him the next time we play cards.\n\nRaschal can hold his own in a fight, and gnolls aren't anything that would get him worried - nay, terrified.  Still, maybe you and yours can act on this new information and make the breakthrough we desperately need." } })
apply(4131, { "classic", "forever" }, { deDE = { completion = "An einen Baum in der Nähe sind zwei große Lederrucksäcke genagelt. Beide tragen auf der Vorderseite klein die Insignien der Festung Feathermoon..." }, enUS = { completion = "Tacked up on a nearby tree are two large leather backpacks.  Each bears a small insignia of the Feathermoon Stronghold on the front of the pack..." } })
apply(4132, { "classic", "forever" }, { deDE = { completion = "Endlich! Der Bösewicht hat seine gerechte Strafe erhalten! Ihr seid ein bemerkenswertes Individuum, {name}. Tragt dieses Medaillon als Symbol Eures unerschütterlichen Engagements zum Wohle der Horde und des KEK." }, enUS = { completion = "Finally! The villain been brought to justice! You are a remarkable individual, {name}. Wear this medallion as a symbol of your stalwart dedication to the Horde and the K.E.F." } })
apply(4133, { "classic", "forever" }, { deDE = { completion = "Vielen Dank, dass Ihr gekommen seid, {name}. Dieser Ort entbehrt nicht eines gewissen rauen Charmes, aber es mangelt an den Annehmlichkeiten des Apothekariums.\n\nDoch genug geplaudert. Kommen wir zum Geschäft, ja?" }, enUS = { completion = "Thank you for coming, {name}.  This place is not without a stark charm, but it lacks the amenities of the Apothecarium.\n\nEnough with the pleasantries.  To business, yes?" } })
apply(4134, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Donnerbräurezept, {name}?", completion = "Sehr gut. Ich schicke dieses Rezept zu Studienzwecken zum Apothekarium, wo man ihm schon bald seine Geheimnisse entlocken wird. Eines Tages werden die Zwerge der Allianz die Vorzüge dieses Getränks am eigenen Leib zu spüren bekommen!\n\nIch finde das höchst amüsant. Vielleicht hat der Tod Auswirkungen auf den Sinn für Humor ... was meint Ihr?" }, enUS = { progress = "Do you have the recipe for the Thunderbrew Lager, {name}?", completion = "Very good.  I will send this recipe to the Apothecarium to be studied, and in time we will unlock its secrets.  One day, the dwarves of the Alliance may find the virtues of this drink used against them!\n\nI find that terribly amusing.  Perhaps death has an affect on one's sense of humor... do you think?" } })
apply(4136, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Ribbly mitgebracht? Oder zumindest einen Teil von ihm?", completion = "Aha! Ihr habt ihn gefunden! Und wie mir scheint, wollte mein kleiner Bruder offenbar nicht freiwillig mitkommen. Wie schade. Ich hätte zu gern sein Gesicht gesehen, wenn ich ihm von unserem Plan, ihn Revilgaz auszuliefern, erzählt hätte.\n\nDanke, {name}. Ihr habt meine Familie sehr glücklich gemacht. Und Ribbly hat nie so friedlich ausgesehen wie jetzt." }, enUS = { progress = "Do you have Ribbly?  Or, at least a part of him?", completion = "Aha!  You found him!  And... it appears that my little brother didn't want to come quietly.  It's a pity.  I would have liked to see the look on his face when I told him our plans to turn him in to Revilgaz.\n\nThank you, {name}.  You've made my family very happy.  And Ribbly's never looked as peaceful as he does now." } })
apply(4141, { "classic", "forever" }, { deDE = { progress = "Larion kann sich auf was gefasst machen, das steht mal fest!", completion = "Ich hoffe, sie haben Euch nicht zu viel Ärger bereitet, {name}. Ich versuche immer, ihnen aus dem Weg zu gehen - sie sind mir einfach zu wild!\n\nEinmal wollte ich über eine drüberspringen... Da griff sie mich an. Das ist doch kein Benehmen für eine Pflanze!" }, enUS = { progress = "Larion's got something coming, that's for sure!", completion = "I hope they didn't give you too much trouble, {name}. I try to steer clear of them -- they're wild!\n\nI tried jumping over one... I was attacked! Plants just shouldn't be acting that way!" } })
apply(4142, { "classic", "forever" }, { deDE = { progress = "Ich lebe hier draußen im Wald... Es ist so friedlich hier.\n\nNa, wenigstens dachte ich das. Ich bekomme hier draußen mehr Besuch als damals, als ich noch in Ironforge wohnte!", completion = "Eine Blutblüte was? Hmmm... Tja, Ihr solltet mir lieber mal erklären, was Ihr vorhabt, dann sage ich Euch, ob ich Euch helfen kann oder nicht." }, enUS = { progress = "I live out here in the forest... Peaceful.\n\nWell, at least I thought it would be. I get more visitors out here than I ever did when I lived in Ironforge!", completion = "Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I'll tell you whether or not I can help you." } })
apply(4143, { "classic", "forever" }, { deDE = { progress = "Larion spricht immer noch nicht mit mir! Wie kann man nur so nachtragend sein!", completion = "Ich muss gestehen, dass ich das Zeug nur sehr ungern anfasse, {name}! Aber wenn Gregan sagt, dass es funktioniert, dann will ich es mal ausprobieren!" }, enUS = { progress = "Larion's still not speaking to me! He sure knows how to hold a grudge.", completion = "I admit, I'm a bit hesitant to touch that stuff, {name}! But if Gregan says it'll work, then I'm willing to give it a try!" } })
apply(4145, { "classic", "forever" }, { deDE = { completion = "Danke für Eure Hilfe, {name}, aber ich fürchte, ich habe schlechte Neuigkeiten..." }, enUS = { completion = "Thanks for your help, {name}, but I'm afraid I have some bad news..." } })
apply(4146, { "classic", "forever" }, { deDE = { progress = "Das kann einen echt fertig machen, {name}. Diese Biester lassen mich einfach nicht in Ruhe!", completion = "Marvon war also nicht da, eh? Na ja, zeigt mir trotzdem, was Ihr da habt." }, enUS = { progress = "This is exhausting, {name}. Those things just won't leave me alone!", completion = "So, Marvon wasn't around? Well, show me what you got, anyway." } })
apply(4147, { "classic", "forever" }, { deDE = { completion = "Marvon ist schon eine ganze Weile fort, {name}. Er wollte nach Tanaris, um dort ein paar der alten Troll-Ruinen zu untersuchen.\n\nAlso, was wolltet Ihr doch noch gleich?" }, enUS = { completion = "Marvon's been gone quite a long time now, {name}. He went off to Tanaris to study some of the ancient troll ruins.\n\nNow, what was it that you said you needed?" } })
apply(4161, { "classic", "forever" }, { deDE = { progress = "Denkt an das Gleichgewicht, {name}. Ich möchte, dass Ihr das Leben im Wald verstehen lernt und Einfühlungsvermögen dafür entwickelt.", completion = "Denkt immer an das, was ich Euch heute gezeigt habe, {name}. Ihr seid Teil des Gleichgewichts, das die Nachtelfen auch in schweren Zeiten aufrechtzuerhalten bestrebt sind." }, enUS = { progress = "Remember the balance, {name}. I wish you to develop an understanding and a strong empathy for the living forests.", completion = "Always remember what I have shown you today, {name}. You are part of the balance that the night elves strive to keep intact, even during troublesome times." } })
apply(4181, { "classic", "forever" }, { deDE = { progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen." }, enUS = { progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something." } })
apply(4182, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Drachenjagd?", completion = "Ausgezeichnete Jagd, {name}. Da wir jetzt wissen, dass Ihr Euch gegenüber den Drachkin behaupten könnt, können wir uns über dringendere Angelegenheiten unterhalten." }, enUS = { progress = "How goes the dragon hunt?", completion = "Superb slaying, {name}. Now that we know you can handle yourself around dragonkin, we can talk of more pressing matters." } })
apply(4184, { "classic", "forever" }, { deDE = { progress = "Was führt Euch zur Burg Stormwind?", completion = "Großdrachen? Unmöglich!" }, enUS = { progress = "What brings you to Stormwind Keep?", completion = "Dragons? Impossible!" } })
apply(4185, { "classic", "forever" }, { deDE = { progress = "<Bolvar betrachtet Euch eindringlich.>", completion = "<Bolvar reibt sein Kinn, als wäre er tief in Gedanken versunken.>\n\nIch respektiere zwar Lady Prestors Haltung, doch glaube ich, dass es für dieses Dilemma eine Lösung gibt, die all unsere Sorgen beseitigen wird." }, enUS = { progress = "<Bolvar watches you intently.>", completion = "<Bolvar cups his chin as if in deep thought.>\n\nWhile I respect Lady Prestor's stance, I believe that there is a solution to this dilemma that may put all of our concerns to rest." } })
apply(4186, { "classic", "forever" }, { deDE = { progress = "Irgendwelche Neuigkeiten von Bolvar?", completion = "Es hätte noch schlimmer kommen können, denke ich...\n\n<Magistrat Solomon betrachtet Euch eingehend.>\n\nEs scheint, als würde Seenhains Schicksal nun allein auf Euren Schultern lasten.\n\n<Ihr bemerkt, dass Magistrat Solomon heftig blinzelt. Er scheint zu weinen.>" }, enUS = { progress = "Any news from Bolvar?", completion = "It could have been worse, I suppose...\n\n<Magistrate Solomon looks you over.>\n\nIt appears as if the fate of Lakeshire rests squarely on your shoulders.\n\n<You notice Magistrate Solomon blinking rapidly. He appears to be crying.>" } })
apply(4201, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Zutaten? Die Leere in meinem Herzen verschlingt mich noch!", completion = "Oh, Ihr habt es geschafft! Jetzt kann ich meinen Trank brauen und ihn Rocknot geben. Endlich wird er meinem Charme verfallen!\n\nIch danke Euch, {name}. Ihr seid ein wahrer Verfechter der Liebe!" }, enUS = { progress = "Do you have the ingredients?  The hole in my heart threatens to consume me!", completion = "Oh, you've done it!  I can now make my potion and use it on Rocknot.  Finally, he will fall victim to my charms!\n\nThank you, {name}.  You are a champion of love!" } })
apply(4223, { "classic", "forever" }, { deDE = { completion = "<Marshal Maxwell lacht.>" }, enUS = { completion = "<Marshal Maxwell laughs.>" } })
apply(4224, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon mit John gesprochen?", completion = "Ich hätte Euch warnen können, aber das wäre nur der halbe Spaß gewesen." }, enUS = { progress = "Have you spoken with John yet?", completion = "I could have warned you, but what fun is that?" } })
apply(4241, { "classic", "forever" }, { deDE = { completion = "Wo ist er? Ich bringe ihn um!" }, enUS = { completion = "Where is he! I'll murder him!" } })
apply(4242, { "classic", "forever" }, { deDE = { completion = "Er ist offensichtlich verrückt geworden.\n\n<Maxwell senkt sorgenvoll den Kopf.>\n\nEs ist bedauerlich, dass ein einst so stolzer und edler Krieger zu solch einem kompletten Schwachkopf mutiert ist. Ich schätze, wir sind in einer Sackgasse...\n\nDennoch muss ich Euch für Eure bisherigen Bemühungen entlohnen, {name}." }, enUS = { completion = "He's gone mad, apparently.\n\n<Maxwell lowers his head in mourning.>\n\nIt is unfortunate that a once proud and noble warrior would be turned into a blithering head case. I GUESS we've reached a dead end...\n\nI must reward you for your efforts thus far, {name}." } })
apply(4243, { "classic", "forever" }, { deDE = { completion = "Als Ihr A-Me 01 eingehend betrachtet, entdeckt Ihr zwei gewaltige Beulen, die Karnas Meisterwerk der Ingenieurskunst verunzieren. Eine Beule befindet sich an der Schulter von A-Me 01, die andere an ihrem Kopf.\n\nDurch ihre Bauteile scheint kein Strom zu fließen, wie Ihr nach weiterer Untersuchung feststellt." }, enUS = { completion = "As you look A-Me 01 over, you see two huge dents tarnishing what Karna obviously feels is a well-crafted piece of engineering. One dent decorates A-Me 01's shoulder, the other is on her head.\n\nNo power seems to be running through her components as you investigate further." } })
apply(4244, { "classic", "forever" }, { deDE = { progress = "Die Abdeckung, in die das Mithrilgehäuse gehört, ist immer noch verschlossen. Der Rest von A-Me 01 bleibt reglos.", completion = "Ihr entfernt wieder die Abdeckung im Rücken von A-Me 01 und nehmt das alte Mithrilgehäuse heraus, das offensichtlich durchgebrannt ist. Das neue klickt problemlos an seinen Platz. Vorausgesetzt, das Mithrilgehäuse war die Ursache des Problems, müsst Ihr jetzt nur noch den Schalter auf 'Aus' und dann wieder auf 'Ein' stellen." }, enUS = { progress = "The panel in which the mithril casing goes is still closed shut. The rest of A-Me 01 remains inert.", completion = "You remove the panel from A-Me 01's back yet again and carefully remove the old mithril casing that seems to have burnt out. The new one slides into place easily. The only thing left to do, assuming the mithril casing was the problem, is to flip the switch to the \"Off\" position, and then back to the \"On\" position." } })
apply(4245, { "classic", "forever" }, { deDE = { completion = "Oh, Ihr habt es geschafft! Großartig! Ich danke Euch, {name}.\n\nOh, meine arme A-Me. Diese Beulen, oh nein! Aber mit Geduld und Spucke werden wir sie im Handumdrehen wieder voll funktionsfähig haben.\n\nNochmals danke, {name}. Ich weiß das wirklich zu schätzen." }, enUS = { completion = "Oh, you've done it! Wonderful! Thank you, {name}.\n\nOh, my poor, A-Me. Look at all those dents. We'll get her up and running perfectly with just a little work.\n\nThank you again, {name}. I really appreciate it." } })
apply(4261, { "classic", "forever" }, { deDE = { completion = "Ja, {name}. Der Teufelswald hat eine Menge durchgemacht. Vielen Dank für Eure Mühen.\n\nEines Tages werden wir den Teufelswald den Klauen der Verderbnis entreißen können. Jede gute Tat trägt dazu bei." }, enUS = { completion = "Yes, {name}. Felwood has been through much hardship. Thank you for what you have done.\n\nOne day, we may be able to reclaim Felwood from the corruption; every kind deed helps." } })
apply(4262, { "classic", "forever" }, { deDE = { completion = "Incendius? Oje..." }, enUS = { completion = "Incendius? Oh dear..." } })
apply(4263, { "classic", "forever" }, { deDE = { completion = "Oje! Seid Ihr sicher, dass Incendius 'Ragnaros' sagte?\n\n<Jalinda gibt Euch etwas und tätschelt Euer Handgelenk, während sie tief in Gedanken versinkt.>" }, enUS = { completion = "Oh dear! Are you sure Incendius said 'Ragnaros?'\n\n<Jalinda hands you something and pats you on the wrist as she fades deep into thought.>" } })
apply(4264, { "classic", "forever" }, { deDE = { progress = "<Marshal Windsor betrachtet die Notiz in Eurer Hand.>\n\nWas bringt Ihr mir da, {name}?", completion = "<Marshal Windsor nimmt die Notiz und beginnt zu lesen.>" }, enUS = { progress = "<Marshal Windsor eyes the note in your hand.>\n\nWhat do you have there, {name}?", completion = "<Marshal Windsor takes the note and begins reading.>" } })
apply(4266, { "classic", "forever" }, { deDE = { completion = "{name}, meinen allerherzlichsten Dank für Eure Hilfe. Eure Tapferkeit angesichts widrigster Umstände verlangt nach einer Belohnung, die tausend Mal größer ist. Ich hoffe dennoch, dass Ihr dies im Namen der gesamten Festung annehmt.\n\nUnd jetzt, wenn Ihr gestattet ... Ich möchte Euch um einen weiteren Gefallen bitten. Angesichts der Entdeckung des Schwarmbaus der Zukk'ash hier in Feralas denke ich, dass Ihr die richtige Wahl für diese Mission seid." }, enUS = { completion = "{name}, I give you my warmest thanks for the aid you've given us.  Your bravery in the face of overwhelming odds has warranted a reward worth a thousand times greater.  Nevertheless, I hope you accept this on behalf of the entire Stronghold.\n\nNow, if I may... I'd like to ask for your aid one more time.  In light of the discovery of the Zukk'ash hive here in Feralas, I think you're the best choice for this mission." } })
apply(4267, { "classic", "forever" }, { deDE = { progress = "Willkommen in diesem gesegneten Tempel. Die Festung Feathermoon hat mich über Euer Kommen informiert. Habt Ihr den Bericht, den Shandris Feathermoon Euch gebeten hat mir zu bringen?", completion = "Wir Nachtelfen wissen um den Schrecken, von dem in diesem Bericht die Rede ist. Shandris hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden Feralas schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Die Insekten, auf die Ihr und der Kurier gestoßen seid, sind als Silithiden bekannt. Sie sind die Werkzeuge der größten Bedrohung, der sich die Horde und die Allianz gegenübersehen.\n\nIch bete darum, dass wir die Entschlossenheit besitzen, sie zu besiegen, bevor sie uns vernichten." }, enUS = { progress = "Welcome to this blessed temple, friend.  Your arrival here from Feathermoon Stronghold has been foretold to me.  Do you have the report Shandris Feathermoon asked you to bring?", completion = "We night elves know of the terror outlined in this report.  Shandris was wise to send this, and you, to me.\n\nThese creatures will consume Feralas rapidly; they are nothing short of one of the greatest menaces we all will ever face.  The insects you and the courier encountered are known as the silithid.  They are mere tools of one of the greatest threats that both the Horde and Alliance will ever face.\n\nI pray we will have the resolve to defeat them before they destroy us." } })
apply(4281, { "classic", "forever" }, { deDE = { progress = "Willkommen in Thalanaar, {class}. Kann ich Euch irgendwie behilflich sein?", completion = "Elune sei gepriesen, die Lieferung von der Festung Feathermoon ist endlich eingetroffen!\n\nEure Anwesenheit hier sagt mir, dass Raschal, unseren eigentlichen Kurier, wohl ein böses Schicksal ereilt hat. Ich hoffe, dass sich alles zum Guten wenden wird. Ich weiß, dass die Waldpfoten seit kurzem wegen irgendetwas, das sich südlich von ihnen ereignet hat, äußerst aufgebracht sind. Vielleicht ist er dort der Wildnis zum Opfer gefallen. Ich an Eurer Stelle wäre vorsichtig.\n\nNun denn, nochmals danke. Hier ist Eure Entlohnung für die Auslieferung des Pakets." }, enUS = { progress = "Welcome to Thalanaar, {class}.  Do you need assistance of some sort?", completion = "Elune be praised, the delivery from Feathermoon Stronghold has finally arrived!\n\nYour presence here indicates to me that perhaps some ill fate may have befallen Raschal, our usual courier.  I hope that everything works out.  I know that recently, the Woodpaw have become highly agitated from some source to their south.  Maybe he fell to the wilds there; I would be careful, friend.\n\nRegardless, thank you again.  Here is payment for this parcel's delivery." } })
apply(4282, { "classic", "forever" }, { deDE = { progress = "Schon bald wird es mit dieser grandiosen Täuschung ein Ende haben.", completion = "<Marshal Windsor reißt die zwei Schrifttafeln aus Eurer Hand.>\n\nWir müssen hier raus!" }, enUS = { progress = "Soon this grand subterfuge will be over.", completion = "<Marshal Windsor snatches the two tablets from your hands.>\n\nWe need to get out of here!" } })
apply(4283, { "classic", "forever" }, { deDE = { progress = "<Oralius spricht mit einem ziemlich großen, abgetrennten Ogerohr.>\n\nBrennende Steppe an Zentrale. Zentrale, bitte kommen.", completion = "Ihr habt es geschafft! Und das ist Eure Belohnung: STREICHELT MEINEN BAUCH! LOS DOCH! STREICHELT IHN!" }, enUS = { progress = "<Oralius is talking into a rather large, severed ogre ear.>\n\nBurning Steppes to control, come in control.", completion = "You've done it! Your reward is: RUB MY BELLY! GO ON! RUB IT!" } })
apply(4284, { "classic", "forever" }, { deDE = { progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, {name}!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, {name}." }, enUS = { progress = "I just know I'm onto something here, {name}!", completion = "Now I will continue my experiments! Thank you, {name}." } })
apply(4285, { "classic", "forever" }, { deDE = { completion = "Ich weiß, dass die Geschichten wahr sind, {name}." }, enUS = { completion = "I know the stories are true, {name}." } })
apply(4286, { "classic", "forever" }, { deDE = { progress = "Ich kann jetzt nicht, {name}. Ich und Winky müssen zu einer Konferenz.", completion = "<Oralius beginnt, in den hoch aufgetürmten Gürteltaschen herumzuwühlen.>\n\nOH, WUNDERBAR!\n\n<Oralius steckt seine lange Nase in den Berg und nimmt einen tiefen Atemzug.>\n\nKÖSTLICH! Seht Euch nur all die schönen Sachen an!\n\nDa, nehmt Euch auch so'n Ding, {name}. Es sind genug davon da." }, enUS = { progress = "I can't be bothered right now, {name}. Me and Winky got a meeting to attend.", completion = "<Oralius starts rummaging through the mountainous pile of fanny packs.>\n\nOH WONDERFUL!\n\n<Oralius sticks his large nose into the pile and takes a whiff.>\n\nDELICIOUS! Look at all these goodies!\n\nTake one for yourself, {name}. There's plenty to go around." } })
apply(4287, { "classic", "forever" }, { deDE = { completion = "Un'Goro ist ein sehr seltsamer Ort, {name}. Wenn man den Krater betritt, kommt es einem so vor, als wäre man in einer ganz anderen Welt..." }, enUS = { completion = "Un'Goro is such a strange place, {name}. When you enter the crater, it's as if you are in a completely different world..." } })
apply(4288, { "classic", "forever" }, { deDE = { completion = "Entlang der Ränder des Kraters gibt es viele verborgene Bereiche. Erkundet die gewundenen Pfade, wenn Ihr nicht mehr wisst, wo Ihr noch suchen sollt, {name}." }, enUS = { completion = "There are many hidden areas of the crater along the sides. Try exploring the winding paths if you can't think of anywhere else to look, {name}." } })
apply(4289, { "classic", "forever" }, { deDE = { progress = "Haben Euch die Kreaturen hier bereits besiegt, {name}?\n\nLasst Euch doch nicht so leicht entmutigen. Die Un'Goro-Affen aufzuspüren und sie zu besiegen ist keine einfache Aufgabe, auch nicht für einen großen Jäger.", completion = "Ihr habt also Eure Kraft bewiesen und dass Ihr kräftig genug seid, um sogar die großen Affen von Un'Goro zu besiegen - das ist gut. Im Vergleich zu Lar'korwi war das zwar nur eine kleine Herausforderung, aber ich will Euch Euren großen Sieg nicht nehmen.\n\nDiese Pelze werden herrliche Kleidung für meinen Stamm abgeben. Ihr habt mir geholfen und Euch als würdig erwiesen.\n\nBevor Ihr Euch einer anderen Aufgabe annehmt, lasst uns noch der Erdenmutter huldigen und den Geistern der Affen danken, die Ihr getötet habt, damit sie wissen, dass ihr Tod nicht umsonst gewesen ist." }, enUS = { progress = "Have the creatures here bested you already, {name}?\n\nDo not be dissuaded so easily. Tracking and defeating the apes of Un'Goro is no simple task, even for a great hunter.", completion = "So, you have proven strong, strong enough to best the great apes of Un'Goro--that is good. The challenge was small compared to Lar'korwi, but I will not take such a great victory away from you.\n\nThese pelts will make wonderful clothing for my tribe. You have helped me and proven worthy.\n\nBefore you set off on another task, let us give praise to the Earth Mother and thank the spirits of those apes you killed--they must know their deaths will not be wasted." } })
apply(4290, { "classic", "forever" }, { deDE = { progress = "Hört auf meine Worte, {name}. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, {name}. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat." }, enUS = { progress = "Do not take my words lightly, {name}. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, {name}. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh." } })
apply(4291, { "classic", "forever" }, { deDE = { progress = "Seid vorsichtig, {name}. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, {name}. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes." }, enUS = { progress = "Be careful, {name}. Getting close to any of nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, {name}. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death." } })
apply(4292, { "classic", "forever" }, { deDE = { progress = "Lasst Euch nicht von Furcht überwältigen, {name}. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!\n\nNehmt das Fleisch, legt es in dem kleinen Tal ab und reibt es dann mit der Drüse ein. Nur so wird der Tod zu Euch kommen.", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, {name}. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch." }, enUS = { progress = "Do not let fear overpower you, {name}. Fear is the great betrayer... you must remain strong!\n\nTake the meat, place it in the small valley, and then use the gland on it. Only then will death come for you.", completion = "The Earth Mother be praised! You've done it! Fair play to you, {name}. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations." } })
apply(4293, { "classic", "forever" }, { deDE = { progress = "Für unsere Kontrollgruppe brauche ich mindestens fünf verderbte Proben, {name}. Sammelt weiter Teufelswaldschleimproben, bis Ihr mir das geben könnt, was wir brauchen. Lady Sylvanas hat es verfügt...", completion = "Ah, wunderbar. Diese Proben sind genau richtig. Ich danke für Eure Hilfe.\n\nSobald wir alle Brühschleimerproben zusammenhaben, können wir mehr sagen. Langsam fange ich an zu glauben, dass Lady Sylvanas mit ihrer Ahnung nicht nur Recht hatte, sondern dass diese auch noch mit mehr Einsicht gesegnet war, als sogar sie gedacht hätte. Diese Proben sind sehr interessant. Allein zu sehen, wie sie auf meine Präparate reagiert haben ... hmm, ja, ganz zweifellos müssen wir noch weitere Untersuchungen anstellen." }, enUS = { progress = "I will need at least five corrupted samples for our control group, {name}. Continue to gather Felwood slime samples until you're able to give me that which we'll need. The Lady Sylvanas decrees it...", completion = "Ah, excellent. These samples will do nicely. I thank you for your help.\n\nOnce we've gathered all the samples of slimes, we'll be able to determine more. I am beginning to suspect that Lady Sylvanas' hunch was not only correct, but more insightful than even she could have predicted. These samples are very interesting. Just seeing how they've reacted with my compounds... hmm, yes, we'll definitely need to investigate further." } })
apply(4294, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Wie läuft Eure Suche?", completion = "Einfach erstaunlich, {name}. Dieser Un'Goro Krater birgt wesentlich mehr Geheimnisse als ich dachte. Ich frage mich, was wir noch alles entdecken werden, wenn wir unsere Tests fortsetzen.\n\nWirklich erstaunlich... seht Euch nur an, wie rein diese Proben sind! Hmm... ich frage mich, was das bedeuten könnte. Es scheint sich bei ihnen um Elementare zu handeln, aber... auch noch um mehr. Sie erinnern mich an... die Alten Götter. Deren Spuren haben wir in ganz Azeroth gefunden und jetzt frage ich mich, ob diese Wesen nicht irgendwie mit ihnen verwandt sind.\n\nWir müssen weitere Tests durchführen." }, enUS = { progress = "Yes, {name}? How goes your search?", completion = "Truly amazing, {name}. This Un'Goro Crater is holding many more secrets than I expected. I wonder what else we will discover as we test further.\n\nSimply amazing... look at the purity of these samples. Hmm, I wonder what it could mean. They seem to be elemental in nature, but... something more. They remind me of... of the Old Gods. We've found traces of them throughout Azeroth, and now I wonder if these creatures aren't related to them somehow.\n\nWe shall have to test further." } })
apply(4296, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schriften der Sieben, {name}? Kennt Ihr jetzt die Geheimnisse dieser Schrifttafel?", completion = "Ah, Ihr habt die Schrifttafel gefunden! Und Eure Abschrift ist erstklassig! Seid Ihr sicher, dass Ihr ein {class} seid und kein Schreiber?\n\nHier, bitte sehr, {name}. Nehmt hier die Bezahlung, die ich Euch versprochen habe." }, enUS = { progress = "Do you have the writings of the Seven, {name}?  Have you learned the secrets from their tablet?", completion = "Ah, you found the tablet!  And your transcription is superb!  Are you sure you're a {class} and not a scribe?\n\nHere you are, {name}.  Here is the payment I promised." } })
apply(4297, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Fleisch, {name}? Euer Kleines hier wird bald schlüpfen. Wenn seine erste Mahlzeit nicht ausreicht, wird er die erste Woche vielleicht nicht überleben, und ich möchte nicht, dass das geschieht.\n\nIch will ehrlich zu Euch sein, {name}. Ich bin neidisch, weil Ihr so ein Ei habt und ich nicht. Und ich möchte es nicht bereuen, Euch hier ausgeholfen zu haben.", completion = "Das wird reichen, und wenn ich mich nicht irre, wird Euer Kleines bald schlüpfen. Wie ist das so? Ihr wisst schon, bald Vater zu sein? Haha, Ihr habt wohl nicht damit gerechnet, einmal solche Verantwortung übernehmen zu müssen, was?" }, enUS = { progress = "Find that meat yet, {name}? Your little egg here's just about ready to hatch. If he don't have a good enough first meal, then he might not make it past his first week, and I'd hate for that to happen.\n\nCan't much lie to ya, {name}. I'm jealous of you gettin' this egg to begin with. Don't make me regret helpin' ya out like this.", completion = "These'll do nicely, and if I'm not mistaken, your little egg's just about ready to hatch. How does it feel? You know, you about to be a father? Haha, didn't think ya'd have to deal with such responsibility, now did ya?" } })
apply(4298, { "classic", "forever" }, { deDE = { completion = "Hier, nehmt das Ei... besser, Ihr habt es in der Hand, damit das Junge gleich eine Bindung zu Euch aufbaut und glaubt, Ihr wärt sein Papa.\n\nGlückwunsch, {name}. Ihr habt jetzt ein Kind... sozusagen." }, enUS = { completion = "Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.\n\nCongrats, {name}. You're a parent... kinda." } })
apply(4300, { "classic", "forever" }, { deDE = { progress = "Meine Kunden sind nicht sehr geduldig, {name}. Habt Ihr schon irgendwelche Klauen?", completion = "Ah, die sind hervorragend. Danke, {name}. Und Ihr seid zurück, bevor sie benötigt werden... sehr gut.\n\nVielleicht fertigen wir ja eine Waffe für Euch aus diesen Klauen an. Was meint Ihr?" }, enUS = { progress = "Me clients are not so patient, {name}. Have you gotten any of the claws yet?", completion = "Ah, these do nicely. Thank you, {name}. An' you be here long before they needed... that be good.\n\nMaybe we have a weapon fashioned for you from the claws. What do you say?" } })
apply(4301, { "classic", "forever" }, { deDE = { progress = "U'cha... was für ein großartiges Tier. Riesig und rot, mit Zähnen so lang wie Dolche. Arme so dick wie Baumstämme und so schnell wie der schnellste Berglöwe, den ich je gesehen habe. Ihr solltet Euch glücklich schätzen, ein solches Objekt für die Prüfung Eures Mutes vorzufinden - mein Volk hat seit Generationen keine derartige Kreatur mehr zu sehen bekommen.", completion = "Gut gemacht, {name}. Ich bin erfreut. Heute habt Ihr hier Großes geleistet.\n\nU'cha war einer der größten Affen, die ich je gesehen habe. Die Tatsache, dass Ihr seine Kraft bezwungen habt, zeugt von Eurer eigenen Kraft... und Eurem Mut.\n\nDaher ist es nur angemessen, dass ich Euch dies hier als Zeichen meines Respekts überreiche. Ihr habt es Euch verdient." }, enUS = { progress = "U'cha... the beast was magnificent. Huge and red, with teeth the size of daggers. His arms as thick as tree trunks, and as fast as any mountain lion I have ever laid eyes upon. You should consider yourself lucky to find such a test of bravery--my people would go generations without seeing such a creature.", completion = "Well done, {name}. I am pleased. You have done a great thing here today.\n\nU'cha was one of the greatest apes I had ever seen. The fact that you have bested his strength speaks well of your own strength... and courage.\n\nIt is only fitting that I give you this as a sign of respect. You have earned it." } })
apply(4321, { "classic", "forever" }, { deDE = { completion = "So, {name}. Das ist echt faszinierend... Ich kann nur hoffen, dass meine Diagramme korrekt sind! Ich habe alles in dieser Anleitung zusammengefasst, die ich Euch überlassen werde.\n\nJetzt sollte ich all Eure Fragen zu den Kristallen beantworten können, {name}." }, enUS = { completion = "Alright, {name}. This is fascinating... I can only hope that my diagrams are correct! I compiled everything into this manual, which you can have.\n\nI believe I can answer any questions you have about the crystals now, {name}." } })
apply(4322, { "classic", "forever" }, { deDE = { completion = "Erstaunlich, {name}. Einfach erstaunlich. Windsor ist vor nicht einmal fünf Minuten hier durchgestürmt. Er spuckte große Töne, behauptete jedoch, alles mit Beweisen untermauern zu können. Jetzt ist er auf dem Weg nach Stormwind, um Bolvar und... Lady Prestor damit zu konfrontieren." }, enUS = { completion = "Amazing, {name}. Simply amazing. Windsor stormed through here not five minutes ago. He makes some grand claims but purports that they are supported by his evidence. He is on his way to Stormwind now to confront Bolvar and ... Lady Prestor." } })
apply(4324, { "classic", "forever" }, { deDE = { completion = "Ja, ich suche meinen Bruder. Wir müssen ihn finden und zurückbringen, gesegnet sei sein Herz.\n\nAber wenn wir ihn nicht im Ganzen zurückbringen können... dann reicht auch sein Kopf." }, enUS = { completion = "Yes, I'm looking for my brother.  We must find him and retrieve him, bless his heart.\n\nBut if we can't bring all of him... then his head will suffice." } })
apply(4341, { "classic", "forever" }, { deDE = { completion = "Bitte, lasst es mich erklären." }, enUS = { completion = "Please, let me explain." } })
apply(4342, { "classic", "forever" }, { deDE = { progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Wie Ihr seht, gab es nichts, was ich hätte tun können." }, enUS = { progress = "Allow me to finish telling my story.", completion = "As you can see, there was nothing I could have done." } })
apply(4361, { "classic", "forever" }, { deDE = { completion = "<Wütend schlägt König Magni mit der Faust auf den Tisch.>" }, enUS = { completion = "<King Magni slams his fist down in anger.>" } })
apply(4362, { "classic", "forever" }, { deDE = { completion = "<Prinzessin Bronzebeard weint bitterlich über den Verlust von Imperator Dagran Thaurissan.>\n\nWarum???" }, enUS = { completion = "<Princess Bronzebeard weeps over the loss of Emperor Dagran Thaurissan.>\n\nWhy???" } })
apply(4363, { "classic", "forever" }, { deDE = { completion = "<König Magni Bronzebeard ist sichtlich erschüttert.>\n\nEs scheint, als habe Thaurissan gewonnen - sogar im Tode.\n\nIhr seid entlassen, {name}. Doch ehe Ihr geht, dürft Ihr Euch Eure Belohnung aus dem königlichen Gewölbe auswählen." }, enUS = { completion = "<King Magni Bronzebeard is visibly upset.>\n\nIt seems that even in death, Thaurissan has won.\n\nYou are dismissed, {name}. Before you leave, you may choose your reward from the royal vault." } })
apply(4402, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, {name}! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu." }, enUS = { progress = "Have you finished collecting cactus apples?", completion = "Wonderful, {name}! As promised, here is your cactus apple surprise plus a little something extra." } })
apply(4421, { "classic", "forever" }, { deDE = { completion = "Den Teufelswald von Xavathras zu befreien, ist nur der erste Schritt auf einem langen Weg. Es wird viel Arbeit vonnöten sein, um den Schaden zu beheben, der hier angerichtet worden ist.\n\nIch spüre, dass hier mehr am Werk ist als nur die Satyrn allein, aber die Wahrheit werden wir wohl erst im Lauf der Zeit herausfinden..." }, enUS = { completion = "Ridding Felwood of Xavathras is only the first step in a long process. It will take much work to repair the damage that has been done here.\n\nI sense that there is something much larger than just the satyrs at work here, but we will only know the truth with time..." } })
apply(4441, { "classic", "forever" }, { deDE = { progress = "Hoffentlich wird das Wasser den Geist des Urtums freisetzen, sodass er von nun an in Frieden ruhen kann.", completion = "Danke, {name}. Und jetzt müssen wir hoffen und beten, dass wir den Schaden beheben können, der hier angerichtet worden ist..." }, enUS = { progress = "The water will hopefully release the spirit of the ancient, and allow it to be at peace.", completion = "Thank you, {name}. Now, we must pray that we can undo the damage that has been done..." } })
apply(4442, { "classic", "forever" }, { deDE = { completion = "Mit dem gesegneten Wasser konnte ich die Verbindung zwischen der Flöte und dem Geist des Urtums unterbrechen. Aber ich glaube, dass Ihr, wenn Ihr diese Flöte an einem heiligen Ort verwendet, vielleicht die Geister der Urtume beschwören könnt.\n\nIhr könntet es einmal in den Ruinen im südlichen Teil der Ruinen des Eisenwaldes versuchen. Einst bewohnten viele verderbte Treants diese Gegend und es ist möglich, dass sie sich noch immer dort aufhalten, und sei es auch nur in Geistgestalt." }, enUS = { completion = "With the blessed water, I was able to break the link between the flute and the ancient spirit. I do believe though, that if you were to use this flute in a sacred spot, you may be able to summon the ancient spirits.\n\nPerhaps you might try the ruins in the southern part of Irontree Woods. Many corrupted treants inhabited this area at one time, and it is possible that they may still reside there, even in spirit form." } })
apply(4449, { "classic", "forever" }, { deDE = { progress = "Ich hab nicht ewig Zeit! Beschafft mir schon diese Stücke Seidenstoff! Äh, Geologen. Ich meine Geologen. Schnappt Euch diese Geologen! Sie verdienen es, meinen... na ja, Euren Zorn zu spüren.", completion = "Oh, toll! Fühlt sich auch klasse an!\n\nWas? Ach ja... die Geologen. Denen habt Ihr's gehörig gezeigt, was? Ich kann Euch gar nich' genug danken, {name}. So hab ich 'n bisschen Zeit, hier drin alles fertig zu machen... Äh, ich meine natürlich, jetzt muss ich mir erst mal keine Sorgen machen, dass die so schnell wiederkommen. Also, nochma' danke." }, enUS = { progress = "I ain't got all day! Get me those pieces of silk cloth! I mean geologists. Get those geologists! They deserve to feel my, well... your wrath.", completion = "Oh, this is great! Nice feel to it too!\n\nWhat? Oh, yeah... geologists. Got 'em good, did ya? I can't thank ya enough, {name}. That'll give me some time to finish up in here... Thanks again, {name}." } })
apply(4450, { "classic", "forever" }, { deDE = { progress = "Ja, bitte? Was kann ich für Euch tun, {race}? Ich bin fürchterlich beschäftigt und viele Kunden warten auf meine Dienste. Vielleicht könnt Ihr Euch ein wenig beeilen? Ich will ja nicht unhöflich sein, aber ich habe einfach keine Zeit - nicht, wenn ich mit all meiner Arbeit fertig werden möchte.", completion = "Oh, wie ich sehe, habt Ihr es für angebracht gehalten, einen Teil der Arbeit zu erledigen, um die ich gebeten hatte. Ausgezeichnet. Und ich dachte schon, Ihr wolltet, dass ich etwas für Euch fertige.\n\nDie sind alle perfekt... und es ist auch alles da. Danke, {class}.\n\nEs kann vermutlich nichts schaden, Euch mit etwas zu belohnen... hmm, was würdet Ihr als nützlich erachten?" }, enUS = { progress = "Yes, yes? What can I do for you, {race}? I'm awfully busy and have many patrons requesting my services. Perhaps you can speed things up. I don't mean to be rude, but I just don't have the time if I'm to catch up on all my work.", completion = "Oh, you've seen fit to do some of the work I requested. Excellent. And here I thought you were going to ask me to craft you something.\n\nThese are all perfect... and everything's here. Thank you, {class}.\n\nMaybe it wouldn't hurt to reward you some... hmm, what would you find useful." } })
apply(4451, { "classic", "forever" }, { deDE = { progress = "*hust*\n\nWer is' da? Seht Ihr nich', dass ich beschäftigt bin?", completion = "Da brat mir doch einer... Wie, zum Geier... !? Ihr habt den Schlüssel gefunden! Ich wusste, dass die verdammten Dunkeleisenzwerge ihn versteckt ham, nachdem se mich hier eingesperrt hatten! Vielsten Dank, {name}. Ihr seid echt Spitze! Na, dann dreht jetzt mal den Schüssel rum und lasst den alten Locheed hier raus!" }, enUS = { progress = "*cough*\n\nWho is it? Can't ya see I'm busy?", completion = "Well, I'll be! How in tarnation!? You found the key! I knew them blasted Dark Irons were hiding it after they locked me in here! Thank ya so much, {name}. You're the greatest! Now, just turn the key and let ol' Locheed outta here!" } })
apply(4488, { "classic", "forever" }, { deDE = { completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht." }, enUS = { completion = "So, you've decided to grace my presence again. How kind of you.\n\nMy acolytes wondered if you'd ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame." } })
apply(4489, { "classic", "forever" }, { deDE = { completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht." }, enUS = { completion = "So, you've decided to grace my presence again. How kind of you.\n\nMy acolytes wondered if you'd ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame." } })
apply(4490, { "classic", "forever" }, { deDE = { completion = "Viel Glück, {name}. Ich freue mich schon darauf, Euch in der Zukunft wiederzusehen." }, enUS = { completion = "Good luck, {name}. I look forward to seeing you in the future." } })
apply(4491, { "classic", "forever" }, { deDE = { completion = "Ringo ist in keiner besonders guten Verfassung, {name}, aber ich bin froh, dass ich ihn in einem Stück zurückhabe.\n\nDanke, dass Ihr ihn gefunden habt." }, enUS = { completion = "Ringo's not in the best shape, {name}, but I am glad to have him back in one piece!\n\nThank you for finding him." } })
apply(4492, { "classic", "forever" }, { deDE = { progress = "Wa... Was?", completion = "Oh... Ich bin ja so froh, dass mich jemand gefunden hat..." }, enUS = { progress = "Wha... What?", completion = "Oh... I'm so glad someone found me..." } })
apply(4493, { "classic", "forever" }, { deDE = { completion = "Ja, ich habe vermutet, dass Gracina Euch zu mir geschickt hat. Eure Erfahrung im Kampf gegen diese Biester ist unschätzbar wertvoll - meines Wissens nach hat bisher niemand sonst mit dieser Spezies zu tun gehabt. Was Gracinas Idee betrifft, dass sie aus dem Un'Goro Krater kommen... vielleicht tun sie das tatsächlich. Der Un'Goro ist ein geheimnisvoller und gefährlicher Dschungel westlich von hier. Vielleicht ist er auch der nächste Schritt auf dem Weg herauszufinden, was es mit den Silithiden auf sich hat." }, enUS = { completion = "Yes, I gathered that Gracina sent you to me.  Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before.  As for Gracina's idea that Un'Goro Crater is their heart... perhaps it is.  Un'Goro is a mysterious and dangerous jungle to the west of here.  Perhaps it is also one step closer to figuring out what the silithid are all about." } })
apply(4494, { "classic", "forever" }, { deDE = { completion = "Ja, ich habe vermutet, dass Zilzibin Euch zu mir geschickt hat. Eure Erfahrung im Kampf gegen diese Biester ist unschätzbar wertvoll - meines Wissens nach hat bisher niemand sonst mit dieser Spezies zu tun gehabt. Was Zils Idee betrifft, dass sie aus dem Un'Goro Krater kommen... vielleicht tun sie das tatsächlich. Der Un'Goro ist ein geheimnisvoller und gefährlicher Dschungel westlich von hier. Vielleicht ist er auch der nächste Schritt auf dem Weg herauszufinden, was es mit den Silithiden auf sich hat." }, enUS = { completion = "Yes, I gathered that Zilzibin sent you to me.  Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before.  As for Zil's idea that Un'Goro Crater is their heart... perhaps it is.  Un'Goro is a mysterious and dangerous jungle to the west of here.  Perhaps it is also one step closer to figuring out what the silithid are all about." } })
apply(4495, { "classic", "forever" }, { deDE = { completion = "Ich bin ja so froh, dass Ihr mich gefunden habt, {name}. Woher habt Ihr gewusst, dass ich hier bin?" }, enUS = { completion = "I'm so glad you found me, {name}. How did you know I was here?" } })
apply(4496, { "classic", "forever" }, { deDE = { progress = "Eine geeignete Duftdrüse zu finden, könnte einige Zeit in Anspruch nehmen - die Drüse darf nicht beschädigt sein und das wird durch die Art und Weise, wie Ihr sie Euch beschaffen müsst, nicht gerade erleichtert. Was die Erdproben angeht, so denke ich, dass die sich ziemlich leicht finden lassen sollten.\n\nNun, wie dem auch sei - habt Ihr die Gegenstände, die ich brauche, um den Köder herzustellen?", completion = "Die Duftdrüse, ah ja. Die Membran scheint intakt zu sein - ausgezeichnet. Die Erde... ja, die ist genau richtig. Und jetzt sollte ich in der Lage sein, mit meinen besonderen Zutaten all dies zum perfekten Köder zu verarbeiten.\n\nGebt mir einen Moment Zeit, um den Köder herzustellen, {name}. Sobald er fertig ist, können wir den nächsten Schritt unternehmen, der hoffentlich die Silithiden aufhält, bevor sie Gadgetzan überrennen - und den Rest von Kalimdor." }, enUS = { progress = "Finding a suitable scent gland might take a bit - the gland can't be damaged, but the process of getting one certainly doesn't lend itself to it.  As for the soil, I'd assume it should be easy enough to find.\n\nAnyway, do you have the items I need to make the lure?", completion = "The scent gland, ah yes.  The membrane appears intact - excellent.  The soil, yes, this should work out perfectly.  With my special additions, I should be able to grind all this up into the perfect lure.\n\nGive me a moment to make the lure, {name}.  Once it's ready, we'll be able to enact the next step that may hopefully stop the silithid before they overrun Gadgetzan... and the rest of Kalimdor." } })
apply(4501, { "classic", "forever" }, { deDE = { completion = "Ich habe schreckliche Angst vor den Pterrordax hier! Danke, dass Ihr ihre Anzahl reduziert habt, {name}. Vielleicht fühle ich mich jetzt wieder sicher genug, um mich aus Marshals Zuflucht herauszutrauen." }, enUS = { completion = "I am absolutely terrified of the pterrordax here! Thank you for decreasing their numbers, {name}. Now I might feel safe enough to venture out of Marshal's Refuge." } })
apply(4502, { "classic", "forever" }, { deDE = { progress = "Stimmt es, dass der Vulkan im Un'Goro aktiv ist? Ich bin sicher, ich könnte eine Menge aus der Asche des Vulkans lernen, {name}.", completion = "Diese Proben sind einfach perfekt für meine Studien! Danke, {name}! Ich verspreche auch, dass ich Euch als Erstem von meinen Ergebnissen berichten werde." }, enUS = { progress = "Is it true that the volcano in Un'Goro is active? I'm sure I could learn a lot with some ash from the volcano, {name}.", completion = "These samples will be perfect for my studies! Thank you, {name}! I promise, you'll be the first one I will tell about my findings." } })
apply(4503, { "classic", "forever" }, { deDE = { progress = "Jedes berühmte Fahrzeug braucht einen Namen. Ich dachte, ich nenne es... Pwned!", completion = "Ja, diese Schuppen sind perfekt. Mit diesen Schuppen kriege ich meinen Flieger bestimmt in die Luft!\n\nDanke!" }, enUS = { progress = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!", completion = "Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!\n\nThanks!" } })
apply(4504, { "classic", "forever" }, { deDE = { progress = "Und Tran'rek hat es wieder einmal geschafft - dieser Superkleber wird der letzte Schrei!", completion = "Ja, dieser Teer ist genau richtig...\n\nHe, Moment mal, meine Hände! Ich krieg sie nicht mehr auseinander...\n\nVielleicht war das doch keine so gute Idee. Oh, wartet mal! Superklebeteerentferner! Da steckt das wahre Geld drin!" }, enUS = { progress = "Tran'rek's done it again -- this super sticky glue will be all the rage!", completion = "Yes, this tar is just the stuff...\n\nHey, wait a minute, my hands... I can't seem to get them apart...\n\nMaybe this wasn't such a good idea. Oh, but wait! Super sticky tar remover! That's where the real money is!" } })
apply(4505, { "classic", "forever" }, { deDE = { progress = "Das ist von äußerster Wichtigkeit. Macht Euch jetzt auf den Weg.", completion = "Wohlan denn. Wir müssen einen Weg finden, diese Verderbnis gegen unsere Feinde einzusetzen..." }, enUS = { progress = "This is of utmost importance. Be on your way, now.", completion = "Very well. We must find a way to use this corruption against our enemies..." } })
apply(4506, { "classic", "forever" }, { deDE = { progress = "Jetzt sagt mir nicht, dass Ihr nicht dorthin zurückgehen könnt! Geht schon!", completion = "Exzellent!\n\nDen Verlassenen ist jedes Mittel recht, um die Allianz zu zerschmettern! Das verderbte Wasser wird sich in Zukunft sicherlich noch als nützlich für unsere weiteren Bemühungen erweisen..." }, enUS = { progress = "Don't tell me that you can't go back there! Get going!", completion = "Excellent!\n\nThe forsaken will resort to any means necessary to crush the alliance! The use of the corrupted water will surely prove useful in our future efforts..." } })
apply(4507, { "classic", "forever" }, { deDE = { progress = "Es ist von absoluter Wichtigkeit, dass wir das Gehirn der Königin für unsere Forschungen in die Hände bekommen. Das, was wir bisher in Erfahrung bringen konnten, lässt uns glauben, dass die Silithiden möglicherweise von einer bösartigen Intelligenz kontrolliert werden. Ich wage gar nicht daran zu denken, wer oder was etwas so Heimtückisches wie die Silithiden kontrollieren könnte, {name}.", completion = "Phantastisch, {name}! Wir haben hier und heute einen sehr bedeutsamen Sieg errungen. Es wird einige Zeit dauern, bis wir vollständig verstehen, was genau wir hier haben; aber wir werden das Beste daraus machen, nur keine Sorge.\n\nWas die Silithiden angeht, so glaube ich kaum, dass wir sie bereits in ihrer Gänze gesehen haben. Diese Lösung war zu sauber, es tut mir Leid, das sagen zu müssen." }, enUS = { progress = "Acquiring the queen's brain for our research is absolutely imperative.  From what we have learned, we believe that these silithid are quite possibly being controlled by a malign intelligence.  I shudder to think what could control something as insidious as the silithid, {name}.", completion = "Fantastic, {name}!  We've won quite the victory here today.  It will take some time for us to fully understand what we have here; we'll put it to good use though, don't you worry about that.\n\nAs for the silithid, I genuinely doubt that this was the full extent of their presence.  This is much too clean of a resolution, I'm sorry to say." } })
apply(4508, { "classic", "forever" }, { deDE = { progress = "Es sind alles Dummköpfe, {name}! Sie würden niemals über den eigenen Tellerrand schauen, ob es nicht irgendwo eine größere Bedrohung geben könnte - ihr blinder Hass auf die Horde wird noch unser aller Ende bedeuten! Ich weiß nicht, was ich ihnen noch als Beweis für die Silithidenbedrohung liefern soll - ich kann sie doch nicht in einen der Schwarmbauten werfen, damit sie es mit eigenen Augen sehen!\n\nAber entschuldigt ... Ihr habt Neuigkeiten für mich?", completion = "Ich weiß dies zwar wirklich zu schätzen, aber leider bin ich mir nicht sicher, ob es uns irgendetwas bringen wird. Die Allianz ignoriert alle Bedrohungen, die nicht von der Horde ausgehen, und sogar unsere eigenen Anführer hier in Darnassus können sich nicht darauf einigen, was diese Bedrohung eigentlich ist. Narren wie Fandral Staghelm sind der Ansicht, dass die Silithiden längst nicht die Gefahr aus der Vergangenheit darstellen, für die ich sie halte. Seine Unwissenheit wird nur noch von seiner Arroganz übertroffen.\n\nIhr habt die Bedrohung doch selbst gesehen, {name}. Wir müssen weiterhin alles tun, um die Silithiden zu besiegen!" }, enUS = { progress = "They are fools, {name}!  They cannot even think to look around them for a greater threat; their irrational hatred of the Horde will be the end of us all.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!\n\nI'm sorry, you bring news for my attention?", completion = "While I genuinely appreciate this, I am not sure what good it will do us.  The Alliance ignores threats from any source other than the Horde, and even our own leaders here in Darnassus cannot agree on what exactly this threat is.  Fools like Fandral Staghelm theorize that the silithid are nothing like the threat from the ancient past I claim them to be.  His ignorance is only surpassed by his arrogance.\n\nYou have seen the threat yourself, {name}.  We must remain committed to defeating the silithid!" } })
apply(4509, { "classic", "forever" }, { deDE = { progress = "Es sind alles Dummköpfe, {name}! Sie würden niemals über den eigenen Tellerrand schauen, ob es nicht irgendwo eine größere Bedrohung geben könnte - ihr blinder Hass auf die Allianz wird noch unser aller Ende bedeuten! Ich weiß nicht, was ich ihnen noch alles als Beweis für die Silithidenbedrohung liefern soll - ich kann sie doch nicht in einen der Schwarmbauten werfen, damit sie es mit eigenen Augen sehen!\n\nAber entschuldigt ... Ihr habt Neuigkeiten für mich?", completion = "Ich weiß dies zwar wirklich zu schätzen, aber leider bin ich mir nicht sicher, ob es uns irgendetwas bringen wird. Die Horde ignoriert alle Bedrohungen, die nicht von der Allianz ausgehen. Während Thrall selbst vielleicht sogar handeln würde, wenn ihm die Fakten vorgelegt würden, so wird er doch von allen Seiten mit widersprüchlichem Rat bestürmt. Wenn es nach diesen Narren ginge, dann müssten wir uns pausenlos im Kreis drehen, wenn sie nur der Meinung wären, dass wir der Allianz damit schaden könnten!\n\nIhr habt die Bedrohung doch selbst gesehen, {name}. Wir müssen weiterhin alles tun, um die Silithiden zu besiegen!" }, enUS = { progress = "They are fools, {name}!  They cannot even think to look around them for a greater threat; their irrational hatred of the Alliance will be our undoing.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!\n\nI'm sorry, you bring news for my attention?", completion = "While I genuinely appreciate this, I am not sure what good it will do us.  The Horde ignores threats from any source other than the Alliance.  While Thrall himself might take action were the facts presented to him, he is beset on all sides by conflicting advice.  These fools would have us chase our own imaginary tails were they to think it might catch the Alliance unawares!\n\nYou have seen the threat yourself, {name}.  We must remain committed to defeating the silithid!" } })
apply(4510, { "classic", "forever" }, { deDE = { progress = "Elune'adore, {class}. Was kann ich heute für Euch tun?", completion = "Dieser Bankgutschein ermächtigt mich, einen Gegenstand aus Gracina Spiritmights Konto bei uns zu entnehmen und Euch zu übergeben. Es scheint, als seien Glückwünsche angebracht!" }, enUS = { progress = "Elune'adore, {class}.  What may I do for you today?", completion = "This bank voucher authorizes me to withdraw an item from Gracina Spiritmight's account with us and present it to you.  Congratulations would seem to be in order!" } })
apply(4511, { "classic", "forever" }, { deDE = { progress = "Zug-zug! Wie kann ich Euch heute helfen, {class}?", completion = "Dieser Bankgutschein ermächtigt mich, einen Gegenstand aus Zilzibin Drumlores Konto bei uns zu entnehmen und Euch zu übergeben. Es scheint, als seien Glückwünsche angebracht!" }, enUS = { progress = "Zug zug!  What may I help you with today, {class}?", completion = "This bank voucher authorizes me to withdraw an item from Zilzibin Drumlore's account with us and present it to you.  Congratulations would seem to be in order!" } })
apply(4512, { "classic", "forever" }, { deDE = { progress = "Schon einige meiner bisherigen Experimente waren absolut faszinierend. Ich glaube, mit ein bisschen mehr Arbeit kann ich noch genauer herausfinden, was es mit diesen Kreaturen auf sich hat und welchen Zusammenhang es zwischen ihnen und der Entwicklung des Lebens auf Azeroth gibt - falls ein solcher Zusammenhang überhaupt existiert.\n\nEine meiner Haupttheorien - die allerdings nicht auf sonderlich viel Gegenliebe stößt - ist der Gedanke, dass die Brühschlammer und Brühschleimer irgendwie mit der Erschaffung dieses Planeten zusammenhängen ... fast so, als seien sie eine seiner Ausscheidungen.\n\nAber das kann ich nicht beweisen oder widerlegen, solange ich nicht mehr Proben bekomme.", completion = "Ganz erstaunlich, {name}! Ihr seid nahe genug herangekommen, um eine Probe der verderbten Wesen zu erhalten, und dabei seht Ihr nicht mitgenommener aus als vorher! Danke. Oh, diese Exemplare eignen sich perfekt. Ich kann es kaum erwarten, meine Versuche daran zu beginnen.\n\nWenn ich Recht habe, dann bin ich vielleicht bald einer der größten Wissenschaftler der Forscherliga!\n\nDas wird allen Zwergen beweisen, dass es kein Fehler war, uns Gnomen nach dem Vorfall in Gnomeregan nach Ironforge hineinzulassen." }, enUS = { progress = "Some of the experiments I've done are fascinating. I think with a little more work, I'll be able to figure out the nature of these creatures and how they play into how life developed on Azeroth... if they even have anything to do with it to begin with.\n\nOne of my biggest theories that isn't well liked is the idea that oozes and slimes are tied to the creation of this planet... almost like they're a secretion of it.\n\nBut I can't prove or disprove it until I get more samples.", completion = "Amazing results, {name}! You got close enough to take a sample of the corrupted things, and managed to look no worse for wear! Thank you. Oh, these samples will be perfect. I can't wait to start testing on them.\n\nIf I'm right, I could be one of the Explorers' Leagues greatest scientists!\n\nThat'll prove to all the dwarves that it wasn't a mistake to allow us gnomes into Ironforge  after the Gnomeregan incident." } })
apply(4513, { "classic", "forever" }, { deDE = { progress = "So viel, über das man nachdenken muss. Aber was bedeutet es alles? Und wie wirkt es sich auf die Bevölkerung von Azeroth aus?", completion = "Ihr habt es gefunden? {name}, Ihr seid ein wahrer Schatz. Eure Hingabe und Eure Hilfe waren einfach fabelhaft und ich kann Euch gar nicht genug danken.\n\nBitte, nehmt dies für Eure Mühen. Es wartet Arbeit auf mich, aber ich bin sicher, dass ich Eure Dienste erneut in Anspruch nehmen werde, wenn Ihr später wiederkommt.\n\nDanke. Vielen herzlichen Dank." }, enUS = { progress = "So many things to consider. But what does it mean? And how does it affect the lives of the people of Azeroth?", completion = "You've found it? {name}, you are a treasure unto yourself. Your dedication and aid has been magnificent and I could not possibly thank you enough.\n\nPlease, take this for your troubles. I have some work to do, but I'm sure, if you come back at a later time, I'll have need of your services again.\n\nThank you. Thank you so much." } })
apply(4521, { "classic", "forever" }, { deDE = { completion = "Das sind ausgezeichnete Neuigkeiten, {name}. Jetzt, wo diese Bestien aus dem Weg geschafft sind, können wir uns weiter nach Winterspring hineinwagen. Seid Ihr bereit für neue Taten?" }, enUS = { completion = "This is excellent news, {name}. With these beasts out of the way, we can begin to adventure further into Winterspring. Are you ready for more?" } })
apply(4581, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Ah, Shindrells Bericht! Vielen Dank, {name}. Shindrell ist, wie eine gute Schildwache sein muss: mutig und aufmerksam. Ich muss das hier lesen; vielleicht finden sich darin Hinweise auf ein Übel, von dem ich fürchte, dass es durch Ashenvale zieht." }, enUS = { progress = "Do you have something for me?", completion = "Ah, Shindrell's report!  Many thanks, {name}.  Shindrell is a fine sentinel, brave and keen.  I must read this for clues of a wickedness I fear is moving through Ashenvale." } })
apply(4601, { "classic", "forever" }, { deDE = { progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftig peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt während er hin und her schlingert..." }, enUS = { progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in a frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side..." } })
apply(4602, { "classic", "forever" }, { deDE = { progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt, als er hin und her schlingert..." }, enUS = { progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side..." } })
apply(4641, { "classic", "forever" }, { deDE = { completion = "Wieder einer von Kaltunks Rekruten, was?\n\nEs ist wirklich schlecht um die Horde bestellt, wenn das das Beste ist, was wir auf die Beine stellen können. Einerlei. Wenn es so weit ist und wir erkennen, dass Ihr bereit seid, das Tal zu verlassen, werdet Ihr ein stolzer Krieger der Horde sein." }, enUS = { completion = "Another one of Kaltunk's recruits, hm?\n\nA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you're ready to leave the Valley, you'll be a proud warrior of the Horde." } })
apply(4642, { "classic", "forever" }, { deDE = { progress = "Wie läuft das Experiment, {name}? Ich werde weiter die Proben studieren, die Ihr mir beschafft habt - langsam verstehe ich, warum sich Lady Sylvanas so sehr für diese Kreaturen interessiert. Sollten sie wirklich ein Teil der Alten Götter sein, wer weiß, wie wir das zu unserem Vorteil ausnutzen können ...", completion = "Oh, ganz ausgezeichnet, {name}. Wirklich ganz ausgezeichnet.\n\nWas für eine Geschichte. Wer hätte gedacht, dass die beiden auf diese Weise miteinander interagieren würden... Ich muss mich wohl eingehender mit den Umweltbedingungen auseinander setzen, die diese Veränderungen in den Kreaturen auslösen.\n\nAlso werde ich meine Forschungen jetzt fortsetzen. Vielleicht sehen wir uns bald wieder. Bis dahin wünsche ich Euch alles Gute." }, enUS = { progress = "How goes the experiment, {name}? I will continue to study the samples you've recovered for me--I am starting to see why Lady Sylvanas is so interested in these creatures. If they are truly part of the Old Gods, then who knows how it can be used to our benefit.", completion = "Oh, most excellent, {name}. This is most excellent.\n\nSuch a tale. Who would have thought the two would interact with one another in such a way... I will have to spend more time looking at the environmental issues that cause changes in these creatures.\n\nI will continue my research for now. Perhaps we will speak again soon. Until then, I wish you well." } })
apply(4681, { "classic", "forever" }, { deDE = { progress = "Sobald Ihr die Überreste der Kreatur in den Gewässern westlich von hier untersucht habt, kann ich einen ordentlichen Bericht für den Tempel des Mondes in Darnassus verfassen. Vielleicht sind wir dann etwas näher an der Lösung des Rätsels, warum diese armen Kreaturen sich dazu entschlossen haben, ihr Leben an der Küste von Dunkelküste auszuhauchen.", completion = "Ihr seid mir hier und heute eine große Hilfe gewesen. Jetzt haben wir eine reelle Chance, hinter das Geheimnis zu kommen, warum diese Kreaturen sich an den Ufern von Dunkelküste auf den Strand werfen. Der Gedanke, dass sie vielleicht aus der Gegend um Teldrassil fliehen, ist beunruhigend. Solltet Ihr auf Euren Reisen auf andere, ähnliche Kreaturen treffen, dann lasst es mich bitte wissen. Wir befinden uns mit unserer Forschung noch ganz am Anfang.\n\nBitte, nehmt im Namen des Tempels des Mondes dies als Dank für Eure Bemühungen an. Danke, {name}!" }, enUS = { progress = "Once you have investigated the creature's remains in the water to the west of here, I should be able to file a proper report with the Temple of the Moon in Darnassus.  Perhaps then we will be closer to discovering the reason why these unfortunate creatures choose to end their lives beached on the coast of Darkshore.", completion = "You've been a tremendous help here today; we now have a solid chance at unlocking the mystery of why these creatures choose to beach themselves on the coast of Darkshore.  The idea that they might be fleeing the area around Teldrassil is disturbing.  Should you come across others in your travels, please let me know.  Our research here is but in its infancy.\n\nOn behalf of the Temple of the Moon, please accept this as thanks for the effort you have given.  Thank you, {name}!" } })
apply(4701, { "classic", "forever" }, { deDE = { completion = "Denkt nicht länger über ihr Leiden nach, {name}. Jene Bestie war verderbt - ein Produkt dunkler Magie. Ihr habt der Allianz einen großen Dienst erwiesen und sollt dafür belohnt werden." }, enUS = { completion = "Do not dwell upon her suffering, {name}. The beast was corrupt - a product of dark magic. You have done the Alliance a great service and you shall be rewarded." } })
apply(4721, { "classic", "forever" }, { deDE = { completion = "Vor harter Arbeit habe ich großen Respekt, {name}. Jetzt können wir unsere Pläne mit Winterspring weiter vorantreiben." }, enUS = { completion = "Hard work is something I have great respect for, {name}. Now we can move forward with our plans for Winterspring." } })
apply(4722, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}... habt Ihr irgendwelche Kreaturen entdeckt, die an Land gespült wurden und von denen Ihr mir berichten wollt?", completion = "Eine weitere Entdeckung, die wir untersuchen können - gut gemacht, {name}! Diese Überreste werden gründlich untersucht, sobald sie in Darnassus ankommen. Bitte nehmt dieses kleine Honorar an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt." }, enUS = { progress = "Hello {name} - do you have any discoveries of creatures that have washed ashore to report on?", completion = "Another discovery for us to research - well done {name}!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study." } })
apply(4723, { "classic", "forever" }, { deDE = { progress = "Vielleicht werden wir eines schönen Tages einen Weg finden, wie wir verhindern können, dass diese armen Kreaturen ohne jeden Sinn und Zweck ihr Leben an den Ufern von Dunkelküste aushauchen. Doch bis dahin müssen wir unsere Forschungen fortsetzen!\n\nSeid gegrüßt, {name}... welche Neuigkeiten bringt Ihr?", completion = "Noch eine Entdeckung, gut gemacht, {name}! Diese Überreste werden gründlich untersucht, sobald sie in Darnassus ankommen. Bitte nehmt dieses kleine Honorar an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt." }, enUS = { progress = "Perhaps one day we'll find a means to prevent these poor creatures from ending their lives needlessly on the coast of Darkshore.  Until then, we must continue our research!\n\nGreetings {name} - what news do you bring?", completion = "Another discovery - well done {name}!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study." } })
apply(4724, { "classic", "forever" }, { deDE = { completion = "Tollwütige Welpen? Gizrul der Geifernde? Und Ihr seid noch am Leben, um davon zu berichten?! Unglaublich! Diese Belohnung habt Ihr Euch wohl verdient!" }, enUS = { completion = "Rabid pups? Gizrul the Slavener? And you live to tell the tale?! Incredible! A tribute well earned!" } })
apply(4725, { "classic", "forever" }, { deDE = { progress = "Es ist mir eine Freude, Euch wiederzusehen, {name}. Zwar machen wir große Fortschritte bei der Lösung des Rätsels, warum so majestätische Meereskreaturen sich selbst an den Ufern von Dunkelküste auf Strand setzen, aber es kommt mir so vor, als würde jede beantwortete Frage zwei neue aufwerfen.\n\nSeid Ihr hier, um uns bei unseren Forschungen behilflich zu sein?", completion = "Ich habe schon von solchen Sänften gehört, wie Ihr sie auf dem Rücken jener Meeresschildkröte gefunden habt. Ich glaube, es handelt sich dabei um Nagasänften, die diese sowohl im Kampf verwenden als auch, um Vorräte an Land zu befördern. Die Zeichen auf dem Kasten, den Ihr gefunden habt, stammen von den Naga - das könnte auch ihr massiertes Eindringen im nördlichsten Teil von Dunkelküste erklären.\n\nIch schicke diesen Kasten nach Darnassus, zusammen mit Euren übrigen Entdeckungen. Das ist für Euch - nochmals danke für Eure Hilfe." }, enUS = { progress = "It is a pleasure to see you again, {name}.  We are making great strives in uncovering the mystery of why majestic sea creatures beach themselves on the Darkshore coastline, but with every question answered, two more are raised it seems.\n\nAre you here to offer us more aid in our research?", completion = "I have heard of the kinds of carriages found on the back of the turtle you found.  Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land.  The markings on the box you found are of the naga; this would explain their invasive presence in far-northern Darkshore.\n\nI will send this box to Darnassus along with the rest of your discoveries.  This is for you - thank you again for your assistance." } })
apply(4726, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Brutlingessenz, {name}? Ich kann es kaum erwarten, sie zu studieren.\n\nUnd ganz abgesehen davon, ist mein Kunde nicht gerade jemand, den man gern enttäuscht...", completion = "Es hat geklappt! Ihr habt die Essenz! Gut gemacht, {name}! Gut gemacht!\n\nDiese Essenz wird für meine Forschungen von unschätzbarem Wert sein. Ich hoffe, dass ich eines Tages herausfinden werde, wie ich lebende Großdrachenwelpen einfangen oder mir zumindest ihre Eier beschaffen kann. Wenn mir dies gelänge, dann würden mich alle Drachenforscher auf der ganzen Welt beneiden!\n\nMein Auftraggeber wäre auch zufrieden - und wie ich schon sagte, ist er jemand, den man besser zufrieden stellen sollte ..." }, enUS = { progress = "Do you have the broodling essence, {name}?  I can't wait to study it.\n\nAnd besides that... my patron is not the type of person you want to disappoint.", completion = "It worked!  You got the essence!  Well done, {name}!  Well done!\n\nThis essence will be invaluable in my research.  I hope to one day learn how to capture living dragons whelps, or perhaps capture their eggs.  If I could find a way to do that, then I would be the envy of dragon scholars around the world!\n\nMy employer would also be happy, and as I said before, he's someone you want to keep happy..." } })
apply(4727, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}, habt Ihr weitere gestrandete Kreaturen gefunden, über die der Tempel des Mondes Bescheid wissen sollte?", completion = "Es ist interessant, dass an der Stelle keine Murlocs waren. Das dürfen wir nicht außer Acht lassen, wenn wir die Überreste dieser Kreatur untersuchen. Ich danke Euch für Eure Bemühungen, {name}. Im Namen des Tempels des Mondes soll ich Euch dies geben, zur Entschädigung für die von Euch aufgewendete Zeit." }, enUS = { progress = "Hello once again {name} - have you found any more beached creatures that the Temple of the Moon should know about?", completion = "It is interesting that the murlocs were not present at this site; we will keep this in mind as we study this creature's remains!  Thank you for your effort, {name}; the Temple of the Moon would like for me to give you this, as compensation for your time." } })
apply(4728, { "classic", "forever" }, { deDE = { progress = "Seid mir erneut gegrüßt, {name}! Was führt Euch nach Auberdine zurück? Seid Ihr vielleicht hier, um mir von einer weiteren Entdeckung zu berichten?", completion = "Ah, ich glaube, das, was Ihr da entdeckt habt, wurde früher schon einmal von der Forscherliga untersucht. Die Liga ist hier in Dunkelküste aktiv und ihre Leute haben erzählt, dass sie dabei waren, eine der gestrandeten Kreaturen zu untersuchen, bis sie von den Murlocs vertrieben wurden. Es scheint, als hättet Ihr dort Erfolg gehabt, wo dies bislang keinem von uns vergönnt war. Bitte, nehmt dieses Honorar im Namen des Tempels des Mondes an." }, enUS = { progress = "Greetings once again, {name}!  What brings you back to Auberdine?  Are you here to report on another discovery, perhaps?", completion = "Ah, I believe you discovered one that was originally being examined by the Explorer's League.  They have a presence here in Darkshore, and they had mentioned that they were studying one of the beached creatures until they were chased out by the murlocs.  You appear to have succeeded where we both have not.  Please - accept this honorarium on behalf of the Temple of the Moon." } })
apply(4729, { "classic", "forever" }, { deDE = { progress = "<Kibler streitet sich gerade mit Toucan Stan.>", completion = "Ihr habt sie gerade noch rechtzeitig erwischt, {name}. Wenig später, und sie hätten nicht mehr ausgebildet werden können! Gebt mir eine Minute, dann könnt Ihr den kleinen Kerl mit nach Hause nehmen." }, enUS = { progress = "<Kibler is busy arguing with Opus.>", completion = "You got 'em at the perfect time, {name}. Any later and they'd be untrainable! Gimmie a minute and I'll have the little fella ready for you to take home." } })
apply(4730, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}! Seid Ihr hier, um mir von einer weiteren Entdeckung zu berichten?", completion = "Die Knochen, die Ihr da habt, stammen von sanftmütigen Meeressäugern, die, wie wir wissen, die Wasser rund um Teldrassil bewohnen. Es war bisher noch nicht bekannt, dass diese Kreaturen sich selbst gewaltsam auf Strand setzen, so wie wir das von den Dreschern kennen. Warum sollten sie das tun, frage ich mich? Nun ja, vielleicht bringt uns das Studium ihrer Überreste dem Wissen näher, nach dem wir streben.\n\nNochmals danke für Eure Hilfe. Bitte, nehmt dieses Honorar vom Tempel des Mondes an." }, enUS = { progress = "Hello again, {name}!  Are you here to report on another discovery?", completion = "The bones you have are from gentle sea mammals that are known to inhabit the waters surrounding the base of Teldrassil.  They had never been known to violently beach themselves like the threshers had been known to.  Why would these creatures do this, I wonder?  Well, perhaps the study of their remains will bear the fruits of knowledge that we seek.\n\nAgain, thank you for your aid.  Please accept this honorarium from the Temple of the Moon." } })
apply(4731, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Ihr habt für den Tempel des Mondes wirklich ganz hervorragende Arbeit geleistet. Dürfen wir darauf hoffen, dass Ihr Eure Bemühungen auch weiterhin auf unsere Sache konzentrieren werdet?", completion = "Ich habe schon von solchen Sänften gehört, wie Ihr sie auf dem Rücken jener Meeresschildkröte gefunden habt. Ich glaube, es handelt sich dabei um Nagasänften, die diese sowohl im Kampf verwenden als auch, um Vorräte an Land zu befördern. Die Zeichen auf dem Kasten, den Ihr gefunden habt, stammen von den Naga ... könnte die Kreatur, die Ihr entdeckt habt, getötet worden sein, als sie gerade unterwegs nach Süden war... nach Ashenvale vielleicht?\n\nIch werde es nicht versäumen, diesen Kasten zusammen mit Euren übrigen Entdeckungen nach Darnassus zu schicken. Das ist für Euch - nochmals danke für Eure Hilfe." }, enUS = { progress = "Hello again, {name}.  The work you have done on behalf of the Temple of the Moon has been outstanding.  Are we to be blessed with more of your effort on our behalf?", completion = "I have heard of the kinds of carriages found on the back of that turtle.  Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land.  The markings on the box you found are of the naga; perhaps the creature you discovered was killed as it was heading further south... to Ashenvale maybe?\n\nI will be sure to send this box to Darnassus with the rest of your discoveries.  This is for you - thank you again for your assistance." } })
apply(4732, { "classic", "forever" }, { deDE = { progress = "Seid mir gegrüßt, {name}... habt Ihr noch weitere Entdeckungen, von denen Ihr dem Tempel des Mondes berichten wollt?", completion = "Ihr habt noch weitere gestrandete Kreaturen gefunden, {name}? Die Meeresschildkröten tummelten sich für gewöhnlich in den Wassern am Fuße von Nordrassil, bevor er zerstört wurde. Doch seit der Entstehung von Teldrassil sind diese Wesen immer seltener gesichtet worden. Manche beenden ihr Leben hier, wie wir entdeckt haben - aus uns völlig unbekannten Gründen.\n\nMit Eurer Hilfe können wir dem Geheimnis vielleicht auf die Spur kommen. Bitte nehmt dies an, im Tausch für die Überreste, die Ihr uns zum Studium übergeben habt." }, enUS = { progress = "Greetings once again {name} - do you have any more discoveries to report to the Temple of the Moon?", completion = "You've found even more beached creatures, {name}?  Sea turtles were commonly found frolicking along the base of Nordrassil before it was destroyed.  With the birth of Teldrassil, however, these creatures have been seen in ever decreasing numbers.  Some, as we have discovered, end their lives here for some unknown reason.\n\nYour aid will perhaps unlock the mystery before us.  Please accept this in exchange for the remains you have provided for our study." } })
apply(4733, { "classic", "forever" }, { deDE = { progress = "Elune sei Dank - Ich freue mich, Euch wiederzusehen, mein lieber {name}. Der Tempel des Mondes beschäftigt sich weiterhin mit dem seltsamen Phänomen der hier in Dunkelküste gestrandeten Kreaturen. Habt Ihr vielleicht wieder etwas, das uns weiterhelfen könnte?", completion = "Die Ausmaße des Dreschers, von dem Ihr erzählt, lassen sich kaum vorstellen. Selbst die ältesten Drescher in dieser Gegend erreichen nur einen Bruchteil dieser Größe. Zwar war bekannt, dass um Teldrassil herum größere Drescher zu finden waren, doch hat ihre Zahl ständig abgenommen. Ich kann mir nicht helfen, ich frage mich, ob die Kreaturen, die sich selbst hier auf Strand setzen, irgendwie damit zu tun haben.\n\nWir werden die Knochen analysieren, die Ihr uns gebracht habt. Bitte, nehmt dies so lange im Namen des Tempels des Mondes an. Danke, {name}." }, enUS = { progress = "Thanks be to Elune - I am glad to see you again, dear {name}.  The Temple of the Moon's work on the strange beaching phenomena continues here in Darkshore.  Might you have anything additional to offer us?", completion = "The dimensions of the thresher you mention are mind-boggling.  Even the eldest of the threshers in this region grow to only a fraction of that size.  While some larger ones were known to be close to Teldrassil, their numbers have declined steadily.  I cannot help but wonder if these creatures beaching themselves here are somehow related to this.\n\nWhile we analyze the bones you have brought us, please accept this on behalf of the Temple of the Moon.  Thank you, {name}." } })
apply(4734, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr das Eiszilloskop getestet?", completion = "Es hat funktioniert? Ausgezeichnet! Ich hab's gewusst!\n\nWährend Ihr weg wart, habe ich an einer neuen Version des Eiszilloskops gearbeitet. Es hat jetzt eine viel größere Reichweite.\n\nHier, Ihr könnt eines davon haben, falls Ihr noch mal zur Blackrockspitze zurückgeht." }, enUS = { progress = "{name}, did you test the eggscilloscope?", completion = "It worked?  Splendid!  I knew it would!\n\nWhile you were gone I was working on a new version of the eggscilloscope.  This one has a much longer range.\n\nHere, you can have one in case you go back to Blackrock Spire." } })
apply(4735, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Eier, {name}? Mein Kunde hat gehört, dass Ihr sie für mich sammelt, und ist sehr begierig darauf, sie in die Finger zu bekommen!", completion = "Wahnsinn, Ihr habt sie! Das kollektronische Modul hat funktioniert! Ich bin ein Genie!\n\nDanke, {name}. Mein Kunde wird äußerst erfreut sein, dass er diese Eier bekommt..." }, enUS = { progress = "Do you have the eggs, {name}?  My patron heard you were collecting them for me, and is very eager to get his hands on them!", completion = "Wow, you got them!  The collectronic module worked!  I'm a genius!\n\nThank you, {name}.  My patron will be very pleased to get these eggs..." } })
apply(4736, { "classic", "forever" }, { deDE = { completion = "Ah, Briarthorn hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt." }, enUS = { completion = "Ah, Briarthorn sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills." } })
apply(4737, { "classic", "forever" }, { deDE = { completion = "Ah, Zevrost hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt." }, enUS = { completion = "Ah, Zevrost sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills." } })
apply(4738, { "classic", "forever" }, { deDE = { completion = "Ah, Demisette hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt." }, enUS = { completion = "Ah, Demisette sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills." } })
apply(4739, { "classic", "forever" }, { deDE = { completion = "Ah, Kaal hat Euch geschickt. Gut. Dann hat es sich also doch weit genug herumgesprochen, dass neue Schüler gesucht werden. Das freut mich.\n\nEs ist typisch für unsereins, {name}, dass wir uns zusammenschließen, ganz gleich, welchem Volk wir angehören. Das ist vor allem wichtig, weil die meisten, mit denen wir es zu tun haben, in ihrer Bosheit keinen Unterschied machen, wenn wir sie nicht besänftigen oder nur unzureichend kontrollieren.\n\nIch spüre, dass Ihr schon vieles gelernt habt, und wenn Ihr wollt, dann helfe ich Euch dabei, die Instrumente zu erschaffen, mit denen Ihr Eure Fähigkeiten ergänzen könnt." }, enUS = { completion = "Ah, Kaal sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills." } })
apply(4740, { "classic", "forever" }, { deDE = { completion = "Na, sieht ganz so aus, als wolltet Ihr etwas mehr, als Euch nur zu erkundigen! Die Bürger werden erleichtert sein zu hören, dass sie heute Nacht ein bisschen sicherer und tiefer schlafen können.\n\nHeute habt Ihr der Gerechtigkeit für das Volk von Auberdine zum Sieg verholfen, {name}. Dafür möchte ich Euch dies als passende Belohnung anbieten - für einen echten Helden des Volkes von Auberdine!" }, enUS = { completion = "Well, looks like you're here to more than just inquire!  The citizens will be delighted to know that tonight they will sleep a little bit more soundly and safer.\n\nYou've acted as the executioner of justice for the people of Auberdine today, {name}.  For that, I would like to offer you this as a suitable reward... for a true hero of the Auberdine people." } })
apply(4741, { "classic", "forever" }, { deDE = { completion = "Ich kann spüren, dass Eure Arbeit Euch Spaß macht. Und ich glaube, wir sind hier etwas auf der Spur." }, enUS = { completion = "I sense that you are enjoying your work. And I believe that we are onto something here." } })
apply(4742, { "classic", "forever" }, { deDE = { progress = "Mut und vor allem Geduld Euch, sterbliches Wesen!", completion = "<Vaelans Bild verschwimmt einen Moment lang.>\n\n<Die Teile, die Ihr gesammelt hattet, sind verschwunden.>\n\nDas ungeschmiedete Siegel des Aufstiegs ist jetzt bereit. Es ist Zeit für den letzten Schritt." }, enUS = { progress = "Courage and patience above all else, mortal!", completion = "<Vaelan's image blurs for a moment.>\n\n<The pieces that you had collected have disappeared.>\n\nThe Unforged Seal of Ascension is now ready. It is time for the final step." } })
apply(4743, { "classic", "forever" }, { deDE = { progress = "Vergeudet keine Zeit, sterbliches Wesen. Nefarian arbeitet fieberhaft daran, sein Übel über unsere Welt zu bringen.", completion = "Bewegt Euch nicht, während ich die letzte Herbeirufung des Schutzes wirke.\n\n<Vaelans Augen werden zu zwei Flammenkugeln.>\n\nDas Siegel des Aufstiegs ist vollendet...\n\nWisset eines: Ich habe das Artefakt mit mächtigem Zauberschutz magieerfüllt. In Eurer dunkelsten Stunde, wenn Ihr glaubt, dass alles verloren ist, dann wird Euch die Kraft des roten Drachenschwarms zur Verfügung stehen." }, enUS = { progress = "Waste no time, mortal. Nefarian works feverishly to unleash his evil upon our world.", completion = "Stand steady while I cast the final invocation of protection.\n\n<Vaelan's eyes turn to twin orbs of flame.>\n\nThe Seal of Ascension is complete...\n\nKnow this, I have imbued the artifact with some powerful protective wards. In your darkest hour, when all appears to be lost, the might of the red flight will be at your disposal." } })
apply(4761, { "classic", "forever" }, { deDE = { completion = "Grüße, {class}. Eure Erkundung der Lage bei den Furbolgs kommt für Auberdine gerade zur rechten Zeit. Wir haben es seit einiger Zeit nicht nur mit Waldbewohnern zu tun, die auf unsere Anwesenheit jetzt ganz offen feindlich reagieren, sondern mit der offensichtlichen Verderbnis des Waldes selbst. Hoffentlich könnt Ihr Auberdine in diesen schwierigen Zeiten helfen." }, enUS = { completion = "Well met, {class}.  Your scouting of the furbolg situation comes at a fortuitous time for us in Auberdine.  For some time we have dealt with not only forest dwellers who are now openly hostile to our presence, but also the outright corruption of the forest itself.  Hopefully you might be able to lend Auberdine aid during these troubling times." } })
apply(4762, { "classic", "forever" }, { deDE = { progress = "Die Verschmutzung des Cliffspring ist nur der Anfang einer alarmierenden Entwicklung hier in Dunkelküste. Die Probe, die Ihr mir gabt, wird uns dabei helfen, einen Plan zu entwickeln. Einen Angriffsplan, wie ich so langsam befürchte.", completion = "Es überrascht mich nicht, dass dieses Wasser so schmutzig ist, aber seht nur, wie faulig es geworden ist! Es sieht so aus, als sollte man lieber umgehend etwas unternehmen, nicht wahr, {name}?\n\nÖstlich von Euch liegt der Teufelswald. Dort ist die eigentliche Quelle dieser Verderbnis, und zwar eine, die ich in der Vergangenheit schon einmal gesehen habe. Ich behaupte, dass diese Probe meine Vermutung bestätigen wird. Vielleicht können wir hier ein Heilmittel entwickeln, aber um es überhaupt versuchen zu können, brauchen wir Unterstützung. Wenn es so weit ist, {name}, hoffe ich, dass Ihr uns Eure Hilfe nicht verweigern werdet." }, enUS = { progress = "The pollution of the Cliffspring River is but the start of an alarming trend here in Darkshore.  The sample you provide will help us formalize a plan... a plan of attack, I am starting to suspect.", completion = "It's no surprise how tainted this water is, but just look at how putrid it is becoming!  It would seem that action is needed sooner than later, eh {name}?\n\nTo our east is Felwood; it is the real source of this corruption, one that I have seen in times past.  I predict this sample will confirm this.  We might be able to enact a cure for it here, but in order to even try we will need assistance.  When that time comes {name}, I hope you will be able to give the aid we need." } })
apply(4763, { "classic", "forever" }, { deDE = { progress = "Der Talisman der Verderbnis ist ein unheilvolles Ding, dessen einziger Zweck darin besteht, das Gleichgewicht der Natur zu stören. An dem Tag, an dem Ihr dem Satyr, der die Furbolgs quält, diesen Gegenstand abnehmt und zu mir bringt, damit ich ihn vernichten kann, haben wir einen großen Sieg errungen!", completion = "Der Krieg zur Rückeroberung unseres Waldes von den Mächten der Verderbnis hat zwar gerade erst begonnen, aber heute haben wir eine Schlacht gewonnen! {name}, das Volk von Auberdine steht tief in Eurer Schuld, die man Euch nur schwerlich vergelten kann. Bitte nehmt dies zusammen mit unserem Dank. Was wir heute hier gelernt haben, kann unsere Freunde, die Furbolgs, vielleicht eines Tages auf Dauer aus den Fesseln der Pein befreien." }, enUS = { progress = "The Talisman of Corruption is a sinister device that only serves to pervert the balance of nature.  When you obtain this item from whatever satyr is tormenting the furbolgs and bring it to me for disposal, we will have won a great victory this day!", completion = "We have just begun this war to reclaim our forest from the forces of corruption, but a battle this day has been won!  {name}, the people of Auberdine owe you a debt of gratitude that will never be easily repaid.  Please accept this along with our thanks.  What we have learned here today may one day free our furbolg friends from the shackles of torment permanently." } })
apply(4764, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schnalle, {name}? Mein Herr wird Euch dafür reichlich entlohnen.", completion = "Ihr habt sie gefunden! Also waren die Gerüchte wirklich wahr!\n\nIch danke Euch, {name}. Mein Herr, Graf Remington Ridgewell, wird überglücklich über dieses neue Stück für seine Sammlung sein." }, enUS = { progress = "Do you have the clasp, {name}?  My patron will pay very handsomely for it.", completion = "You found it!  So the rumors were true!\n\nThank you, {name}.  My patron, Count Remington Ridgewell, will be quite pleased to see this addition to this collection." } })
apply(4765, { "classic", "forever" }, { deDE = { progress = "Man sagte mir, dass ein Bote kommen würde. Einer mit einem Geschenk von der Blackrockspitze.\n\nSeid Ihr das vielleicht?", completion = "Ah, Ihr seid das also! Seid bedankt, {name}. Und falls Ihr es noch nicht wisst... die Dankbarkeit eines Adligen derer von Ridgewell übertrifft selbst die Großzügigkeit eines Königs." }, enUS = { progress = "I was told a messenger would come.  One with a gift from Blackrock Spire.\n\nAre you he?", completion = "Ah, so you are he!  You have my thanks, {name}.  And... if you didn't already know... the gratitude of a noble in the house of Ridgewell is nigh worth a king's ransom." } })
apply(4766, { "classic", "forever" }, { deDE = { completion = "Ihr kommt aus Stormwind? Wunderbar - ich weiß von einem Kunstobjekt, für das Remington alles geben würde, um es seinem Museum einzuverleiben, aber leider ist es nicht einfach zu beschaffen.\n\nUnd hier kommt Ihr ins Spiel." }, enUS = { completion = "You came from Stormwind?  Wonderful -- I know of an object of art that Remington would kill to have in his museum, but extracting it won't be easy.\n\nThat's where you come in." } })
apply(4767, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr die Flügeldracheneier, um die ich gebeten habe? Ich brenne wirklich darauf, so bald wie möglich mit meiner Windreiterausbildung zu beginnen!", completion = "Perfekt! Mit diesen Eiern kann ich hoffentlich die nächste Hürde auf dem Weg zum Windreiter nehmen. Hier habt Ihr ein Zeichen meiner Anerkennung. Möge Eure Jagd immer von Erfolg gekrönt sein, {class}." }, enUS = { progress = "{name}, have you retrieved the wyvern eggs that I seek? I'm really anxious to start my wind rider training!", completion = "Perfect! With these eggs I hope to take the next step to become a wind rider. Here is a token of my appreciation; may good hunting always shine upon you, {class}." } })
apply(4768, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schrifttafel gefunden, {name}? Ich brenne darauf, ihre Geheimnisse zu erfahren.", completion = "Ausgezeichnet. Es wird Tage dauern, bis ich die in diese Schrifttafel eingravierten Formeln erforscht habe, aber ich bin zuversichtlich, dass meine Mühen reichlich Früchte tragen werden.\n\nIch danke Euch, {name}. Ihr habt uns einen unschätzbaren Dienst erwiesen." }, enUS = { progress = "Have you found the Tablet, {name}?  I yearn to delve into its secrets.", completion = "Excellent.  The formulae etched into this tablet will consume days of research, but I am confident such research will bear sweet fruit.\n\nThank you, {name}.  You have been invaluable to us." } })
apply(4769, { "classic", "forever" }, { deDE = { completion = "Das stimmt. Ich glaube, dass es auf der Blackrockspitze eine Schrifttafel gibt, die alte alchimistische Rezepte enthält. Ich bin froh, dass Ihr hier seid, denn ich brauche Hilfe, um an diese Schrifttafel zu gelangen.\n\nMacht es Euch bequem, dann erkläre ich es Euch näher." }, enUS = { completion = "It is true.  I believe there is a tablet held within Blackrock Spire, a tablet that contains old alchemical recipes.  I am glad you are here, for I need help in retrieving the tablet.\n\nMake yourself comfortable, and I will explain further." } })
apply(4770, { "classic", "forever" }, { deDE = { completion = "Was!? Wenn ich gewusst hätte, dass Pao'ka Swiftmountain in der Gegend des Steilhangs herumschnüffeln wollte, hätte ich ihn an ein Totem gekettet! Sein Vater hat ihm nur ungern gestattet, mich nach Tausend Nadeln zu begleiten. Wir kamen hierher, um die verschiedenen Kreaturen zu studieren, die dieses wunderschöne Land bewohnen.\n\nIch weiß es zu schätzen, dass Ihr Pao'ka geholfen habt. Hoffentlich wiegt dies hier alle Unannehmlichkeiten wieder auf, die Ihr dafür in Kauf genommen habt." }, enUS = { completion = "What!? If I knew that Pao'ka Swiftmountain was going to snoop around Highperch, I would have chained him to a totem! His father was reluctant allowing him to come with me to Thousand Needles. We came here to study the different creatures that inhabit these beautiful lands.\n\nI appreciate the help you have shown Pao'ka. I hope this covers any misfortunes this deed has cost you." } })
apply(4771, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft! Vectus ist besiegt! Und die Dämmerungstrickfalle... hat sie funktioniert?\n\nHm... vielleicht war mein Gerät nicht der Erfolg, den ich mir erhofft hatte, aber ich bin froh, dass Ihr die Sache trotzdem bewerkstelligen konntet. Gut gemacht, {name}!\n\nDie Argentumdämmerung und die guten Menschen von Azeroth sind in Eurer Schuld." }, enUS = { completion = "You did it!  Vectus is defeated!  And Dawn's Gambit... did it work?\n\nHm... maybe my device wasn't the success I had hoped, but I'm glad you were able to handle things anyway.  Well done, {name}!\n\nThe Argent Dawn, and the good people of Azeroth, are in your debt." } })
apply(4781, { "classic", "forever" }, { deDE = { progress = "Goldbarren, ja... ja. Bringt mir einen, dann sehen wir, ob ich nicht ein bisschen Garn für Euch spinnen kann. Bis dahin schlage ich vor, dass Ihr Euch zunächst darauf konzentriert, etwas mächtiger zu werden. Die schwersten Aufgaben liegen immer noch vor Euch. Und glaubt mir... Ihr werdet Euch irgendwann wünschen, besser vorbereitet zu sein, so mächtig Ihr Euch momentan auch fühlen möget.", completion = "Perfekt, {name}. Ich bin froh, dass Ihr so schnell einen Minenarbeiter gefunden habt, der Euch helfen konnte. Oder habt Ihr das etwa selbst erledigt? Auf jeden Fall habt Ihr Eure Sache gut gemacht. Das hier eignet sich perfekt, um daraus Garn zu machen.\n\nEs wird jedoch eine Weile dauern, um es zu spinnen, daher solltet Ihr später wiederkommen. Um genau zu sein: Ich muss es einer Prinzessin schicken, die wir in einem Turm eingesperrt haben und deren einzige Aufgabe es ist, Goldfäden zu spinnen ... Nein, wirklich. Das ist mein Ernst ... na gut, ich habe geflunkert." }, enUS = { progress = "Gold bars, yes... yes. Bring me one and we'll see what we can do about spinning some thread for you. Until then, I would suggest you focus your efforts on becoming more powerful. Your toughest trials are still ahead. And trust me... you'll wish you were more prepared, regardless of how powerful you think you might be.", completion = "Perfect, {name}. I'm glad you could find a miner to help you out so quickly. Or did you do this work yourself? Either way, you've done well. This will be perfect for the thread.\n\nIt will take some time to create the stuff, so you'll have to come back--I actually send it off to some princess who we have locked in a tower who's only job is to spin gold thread... no, seriously. I mean it... okay, not really." } })
apply(4782, { "classic", "forever" }, { deDE = { completion = "Gut, Ihr seid zurückgekehrt, {name}. Und wo ist das Garn? Meine Fäden?\n\nAch so, ich verstehe. Da kann man nichts machen. Der Goblin und sein Bruder haben uns bisher noch nie im Stich gelassen - es ist wohl entschuldbar, dass er nicht alles stehen und liegen ließ, um sich sofort an die Arbeit zu machen. Na gut ... es gibt noch andere Dinge, um die wir uns in der Zwischenzeit kümmern können.\n\nSeid Ihr bereit für den nächsten Schritt?" }, enUS = { completion = "Good, you've returned, {name}. And where is the thread?\n\nAh, I understand. That is acceptable. The goblin and his brother have not failed us yet--I suppose it is understandable that he did not have it prepared right then. So be it... we have other things we can attend to in the meantime.\n\nAre you prepared for the next step?" } })
apply(4783, { "classic", "forever" }, { deDE = { progress = "Desolace ist nicht gerade ein freundlicher Ort: Naga, Riesen, Satyrn, die Brennende Legion... all das und sich gegenseitig bekämpfende Zentaurenklans machen das Land äußerst gefährlich, wenn Ihr Euch nicht vorseht.\n\nWie ich schon sagte, wird das alles nicht nur Eure Kraft und Schlauheit auf die Probe stellen, sondern auch Eure Geduld. Seid immer auf der Hut in dieser Gegend, {name}.", completion = "Ausgezeichnet, {name}. Das ist perfekt. Ich werde jetzt alles vorbereiten, während Ihr Euch auf die Suche nach den beiden letzten Komponenten macht. Seid Ihr bereit?" }, enUS = { progress = "Desolace is not a kind area: naga, giants, satyr, the Burning Legion... all of those and warring centaur clans all make the land dangerous if you're not careful.\n\nLike I said before, it will not only test your strength and cunning, but also your patience. Be wary in those lands, {name}.", completion = "Excellent, {name}. These will do nicely. I will prepare them now while you move on to your last two components. Are you ready?" } })
apply(4784, { "classic", "forever" }, { deDE = { progress = "Bald ist es so weit, {name}. Das verspreche ich Euch. Die Robe wird Euren Ansprüchen mehr als gerecht werden und Euch sicherlich gegenüber Euren Feinden einen großen Vorteil verschaffen.", completion = "Exzellent, {name}! Alle Komponenten sind da und wir sind bereit.\n\nIhr werdet höchst zufrieden sein." }, enUS = { progress = "Soon, {name}. I promise you. The robe will be more than adequate for your needs and certainly give you an edge over your opponents.", completion = "Excellent, {name}! The components are gathered and we are ready.\n\nI trust you will be pleased." } })
apply(4786, { "classic", "forever" }, { deDE = { completion = "Es ist vollbracht, {name}. Hier, bitte sehr. Tragt sie mit Stolz.\n\nIhr habt hart dafür gearbeitet und ich sehe große Taten in Eurer Zukunft. Denkt daran: Um sich der Verderbnis zu erwehren, die unseren Weg begleitet, bedarf es eines starken Willens und großer, innerer Stärke. Solange Ihr Herr Eures Willens seid, wird Euch großer Erfolg beschieden sein." }, enUS = { completion = "It is done, {name}. Here you are. Wear it with pride.\n\nYou've worked hard and I see great things in your future. Remember, to defy the corruption that comes with our path takes great will and fortitude. As long as your will is your own, then you shall have great success." } })
apply(4787, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das uralte Ei? Ich spüre, wie sich große Mächte regen, und ich fürchte, dass die Zeit knapp wird.", completion = "Ah, Ihr habt das Ei! Ich verneige mich vor Euch, {name}. An Eure Kraft und Euren Mut wird man sich noch lang erinnern." }, enUS = { progress = "Do you have the ancient egg?  I sense great forces stirring, and I fear that time grows short.", completion = "Ah, you have the egg!  I bow to you, {name}.  Your strength and bravery will be long remembered." } })
apply(4788, { "classic", "forever" }, { deDE = { progress = "Wart Ihr bei der Spitze, {name}? Habt Ihr die fünfte und sechste Schrifttafel?", completion = "Unglaublich! Ihr habt sie gefunden! Ihr seid ein wahrer Held, {name}!\n\nDas ist eine gute Sache, denn ich habe die Schrifttafeln gelesen, die Ihr mir zuvor gebracht habt, und nach dem, was ich herausgefunden habe... tja, da werden wir wohl einen Helden brauchen, der aufhält, was kommt..." }, enUS = { progress = "Have you been to the spire, {name}?  Do you have the fifth and sixth tablets?", completion = "Unbelievable!  You found them!  You truly are a hero, {name}!\n\nThat's a good thing, because I've been reading the tablets you brought me before, and from what I gathered... we're going to need a hero to stop what's coming..." } })
apply(4809, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Hörner der Eiswindschimären, {name}?", completion = "Das sind wirklich Prachtexemplare. Sie sind eiskalt! Ich ziehe mir schnell ein Paar Handschuhe an und dann packe ich sie zu den anderen Dingen, die Tinkee braucht..." }, enUS = { progress = "Do you have the chillwind horns, {name}?", completion = "These are good specimens.  They're packed with cold!  Let me get some gloves on, then pack them along with the other things Tinkee needs..." } })
apply(4810, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr mit Felnok gesprochen? Habt Ihr die Komponenten, die ich benötige?", completion = "Ihr habt sie! Großartig! Ich mache mich sogleich ans Werk! Tausendmal Dank, {name}!\n\nIhr wart mir eine so große Hilfe, dass ich Euch bestimmt einmal wieder für noch wichtigere Aufgaben brauchen könnte..." }, enUS = { progress = "{name}!  Did you talk to Felnok?  Did you bring the components I need?", completion = "You brought them!  Great!  I'll get to work right away!  Thanks a ton, {name}!\n\nYou've been so helpful to me, I might need you for even more important tasks later..." } })
apply(4811, { "classic", "forever" }, { deDE = { completion = "Der Kristall existiert also, {name}? Faszinierend... Ihr habt Eure Aufgabe gut ausgeführt; das war gute Arbeit!\n\nWas genau ist dieser Kristall? Das ist nur eine einzelne Frage in einem Meer von Fragen. Eine weitere Frage, die sich stellt, ist, warum die Moonkin von diesem Objekt angezogen werden... Ist der Kristall von Natur aus gut oder birgt er einen düsteren Zweck?\n\nIch habe viele weitere Fragen, aber wir werden diesen Kristall näher untersuchen müssen, um einige Antworten zu erhalten." }, enUS = { completion = "So the crystal exists, {name}?  Fascinating... anyway, your task has been well executed; good work!\n\nWhat exactly is this crystal?  This is but a single question in a sea of questions.  Another question that comes to mind is why the moonkin would be drawn to this object?  Is the crystal benign in nature, or does it hold a more sinister purpose?\n\nI have many more questions, but we're going to need to examine that crystal closely to get some answers." } })
apply(4812, { "classic", "forever" }, { deDE = { progress = "Gegen die Baumkulisse von Dunkelküste wirkt der Kristall sehr fremdartig. Ihr meint, ein sehr leises Summen aus seinem tiefsten Inneren zu vernehmen.", completion = "Ihr habt den mysteriösen Kristall erneut erreicht. Sogleich entfernt Ihr den Verschluss der Röhre mit Mondbrunnenwasser und gießt den Inhalt vorsichtig über dem Kristall aus. Als das Wasser über das Kristallgitter läuft, seht Ihr, wie seine undurchsichtige Oberfläche durchsichtig wird..." }, enUS = { progress = "The crystal looks very alien against the wooded scenery of Darkshore.  You think you hear a very slight humming coming from deep within it.", completion = "You have made it once more to the mysterious crystal.  Removing the stopper on the tube of moonwell water, you gingerly pour the contents out over the top of the crystal.  As the water cascades down its lattices, you see the opaque surface turn transparent..." } })
apply(4813, { "classic", "forever" }, { deDE = { completion = "Tja, es scheint, dass wir jetzt zwar mehr über den Kristall wissen, dafür aber vor noch mehr unbeantworteten Fragen stehen!\n\nIch werde die Informationen, die Ihr enthüllt habt, zum Rat hier in Auberdine bringen. Vielleicht weiß er, was bezüglich dieses Kristalls zu tun ist. Das heißt, vorausgesetzt, dass es etwas zu tun gibt; vorerst befindet sich die Bedrohung weit genug im Osten, sodass sie für uns keine Gefahr bedeutet.\n\nUnd was Euch angeht, bitte nehmt dies. Seht es als eine Belohnung für gut geleistete Arbeit an, {name}." }, enUS = { completion = "Well, it would seem that even though we know more about this crystal, more unanswered questions are the result!\n\nI'll take the information you've uncovered to the council here in Auberdine.  Perhaps they'll know a course of action to follow on this crystal.  Well, that is if there is one to be taken; for now, the threat remains far enough to our east to be out of harm's way.\n\nAs for you, please have this.  Consider it a reward for a job well done, {name}." } })
apply(4821, { "classic", "forever" }, { deDE = { progress = "Ich muss mehr über dieses mysteriöse Ei herausfinden. Wer weiß, was einmal daraus schlüpfen wird.", completion = "Ja, endlich... das mysteriöse Ei wurde mir endlich gebracht. Dann lasst mich mal einen Blick darauf werfen... Was...! Was ist das...?" }, enUS = { progress = "I must know more about this mysterious egg, who knows what will hatch from it.", completion = "Yes, finally... the mysterious egg has finally been delivered to me. Now, let me take a closer look at this... What..! What is this..?" } })
apply(4841, { "classic", "forever" }, { deDE = { progress = "Kommt schon, {name}, ich weiß, dass Ihr Euren Anteil noch nicht erlegt habt. Bringt sie zur Strecke, dann bekommt Ihr eine Belohnung als Zeichen meiner Dankbarkeit.", completion = "Das ist für Euch, {name}, als Zeichen meiner Dankbarkeit." }, enUS = { progress = "Come now {name}, I know you haven't killed your share yet. Hunt them down, and I shall give you a reward for my gratitude.", completion = "For my gratitude, this is for you, {name}." } })
apply(4842, { "classic", "forever" }, { deDE = { progress = "Das Wasser der Quellen scheint ein paar höchst eigenartige Eigenschaften zu haben... Ich bin mir immer noch nicht sicher, was das zu bedeuten hat...", completion = "Ja, die Dämonen dort in der flüsternden Schlucht... ich glaube, dass es ihre Anwesenheit ist, die das Land auf diese Weise beeinflusst. Ich werde weiter die hiesigen heißen Quellen beobachten und zusehen, ob ich etwas mehr herausfinden kann.\n\nAn Eurer Stelle würde ich allerdings warten, bis ich ein bisschen stärker wäre, bevor ich mich weiter in die flüsternden Schlucht hineinwagen würde." }, enUS = { progress = "The water in the springs seems to have some very odd properties... I am still unsure of what it means...", completion = "Yes, the demons there in Darkwhisper Gorge; I believe it is their presence that is affecting the land in this way. I am going to continue observing the hot springs here and see if I learn anything more.\n\nI'd wait until you are a bit stronger if you have plans of heading farther into Darkwhisper Gorge." } })
apply(4862, { "classic", "forever" }, { deDE = { progress = "Sind das da Spinnen-Eier in Eurem Säckel oder freut Ihr Euch einfach nur, mich zu sehen?", completion = "Was für ein Haufen! Ich meine, seht Euch nur all diese Eier an! Die sollten eine ordentliche Menge Gold einbringen.\n\nWie versprochen, hier habt Ihr Euer eigenes kleines Tierchen. Lasst Euch nur nicht beißen!" }, enUS = { progress = "Are those spider eggs in your pack or are you just happy to see me?", completion = "What a load! I mean, look at all those eggs! These should bring in a right few gold.\n\nAs promised, here's your own little critter. Don't get bitten!" } })
apply(4863, { "classic", "forever" }, { deDE = { completion = "Ihr nähert Euch dem Wagen. Es scheint dort nichts weiter für Jaron zu geben. Als Ihr jedoch zu Boden blickt, fallen Euch ein paar Kisten auf, die unbeschädigt aussehen, aber halb im Schnee verborgen sind." }, enUS = { completion = "Approaching the wagon, it doesn't appear that there is much more here for Jaron. But, looking on the ground, you notice some crates that look undamaged, despite being half-buried in the snow." } })
apply(4864, { "classic", "forever" }, { deDE = { progress = "Aye... Was gibt's Neues?", completion = "Tja, das hatte ich befürchtet zu hören. Hab ich mir doch gedacht, dass diese wahnsinnigen Bestien meine ganzen Habseligkeiten zerstört haben...\n\nAber Ihr habt meine Werkzeuge gefunden und, was noch wichtiger ist, das Amulett! Ich frage mich, warum die Wildekin diesen Gegenstand so heftigst verteidigt haben... Wie auch immer, ich werde es mir zweimal überlegen, ihnen noch einmal in die Quere zu geraten!" }, enUS = { progress = "Aye... Tell me the news.", completion = "Well, I expected to hear as much, lad. I figured that the crazed beasts destroyed all of my belongings...\n\nBut you did find my tools, and most importantly, the amulet! I wonder why the wildkin so fiercely defended this item... In any case, I'll think twice before heading their way again!" } })
apply(4865, { "classic", "forever" }, { deDE = { completion = "Rache! Also ist die Legende von Arikara doch wahr. Das ist in der Tat ein Problem, um das wir uns unverzüglich kümmern müssen." }, enUS = { completion = "Vengeance! So, the legend of Arikara is true. Indeed, this is a problem that must be resolved immediately." } })
apply(4866, { "classic", "forever" }, { deDE = { progress = "<Der struppige John kneift Euch.>", completion = "Das wird das beste Bier aller Zeiten.\n\nHe, was habt Ihr denn gedacht, wofür ich das benutze? Als Gift oder so was???\n\nVerrückte Kinder..." }, enUS = { progress = "<Ragged John pinches you.>", completion = "This is gonna make the best ale yet!\n\nEh, what did you think I was gonna use this for? Poison or something??\n\nCrazy kids..." } })
apply(4867, { "classic", "forever" }, { deDE = { progress = "Ah! Habt Ihr mein Mojo?", completion = "Aha! Ich kann bereits fühlen, wie meine Macht zu mir zurückkehrt. Und meine Gedanken werden nicht mehr von Uroks Fluch gestört.\n\nDanke, {name}! Bescheidenheit ist unter meiner Würde, aber ich muss Eure Hilfe anerkennen.\n\nUnd ich wünsche Euch Glück auf Euren Reisen durch Blackrockspitze. Ihr seid ein Narr zu denken, Ihr könntet es bis an die Spitze schaffen, aber Euer Mut steht außer Frage." }, enUS = { progress = "Ah!  Do you have my mojo?", completion = "Aha!  I can already feel my powers returning to me.  And my mind is no longer wracked by Urok's curse.\n\nThank you, {name}!  Humility is below me, but I must acknowledge your aid.\n\nAnd I bid you fortune in your journeys through Blackrock Spire.  You are a fool to think you could make your way to the top, but your bravery is without question." } })
apply(4881, { "classic", "forever" }, { deDE = { completion = "Die wollen mich töten? Ich werde ihnen zeigen, wie ein Tauren kämpft!" }, enUS = { completion = "They come to kill me?  I will show them how a Tauren fights!" } })
apply(4882, { "classic", "forever" }, { deDE = { progress = "Meldet Ihr Euch für einen weiteren Auftrag?", completion = "Eine bedeutende Entdeckung?" }, enUS = { progress = "Reporting for another assignment?", completion = "An important discovery?" } })
apply(4883, { "classic", "forever" }, { deDE = { progress = "Wie kann ich Euch helfen, {name}?", completion = "Die Energie dieser Halskette, {name}. Ich glaube, dass sie nur eine Quelle hat.\n\n\n\nDie Wildekin, nun fehlgeleitet und verwirrt, waren einst nicht so. Sie hatten einst einen Zweck und wurden geleitet, um zu dienen. Die Nachtelfengöttin Elune hat diese Kreaturen geschaffen, um ihre hochheiligsten Gebiete zu bewachen.\n\nDiese Tatsache mag nicht sehr wertvoll erscheinen, aber ich dränge Euch, weiter zu forschen.\n\nIhr werdet es irgendwann erfahren. Danke, dass Ihr mir dies gebracht habt, {name}." }, enUS = { progress = "How may I help you, {name}?", completion = "The energy of this necklace, {name}. I believe that it has only one source.\n\n\n\nThe wildkin, now misguided and confused, were once not so. They once had a purpose, and were guided to serve. The night elf goddess Elune created these creatures to guard her most sacred areas.\n\nWhile this fact may seem like it holds little value; I urge you to look deeper.\n\nYou will learn, in time. Thank you for bringing this to me, {name}." } })
apply(4901, { "classic", "forever" }, { deDE = { completion = "Habt Ihr Ranshalla getroffen?" }, enUS = { completion = "Did you meet up with Ranshalla?" } })
apply(4902, { "classic", "forever" }, { deDE = { completion = "Nur heraus damit, sagt mir, warum Ihr hier seid.\n\nOh, ja? Hmm. Nun ja.\n\nDanke, dass Ihr damit direkt zu mir gekommen seid. Es ist immer am besten, sich direkt an die Spitze zu wenden... Aber... Ja. Die Druiden des Zirkels des Cenarius wissen schon eine ganze Weile von den Wildekin. Dass sie Tiere von Elune und dazu auserwählt sind, die hochheiligsten Orte zu bewachen.\n\nWenn das also auch keine wirklichen Neuigkeiten waren, so muss ich Euch doch für Eure Anstrengungen loben. Hier, nehmt dies... es ist etwas, das mir für eine solche Tat angemessen erscheint." }, enUS = { completion = "Do not hesitate; tell me why you have come.\n\nOh, yes? Hmm. Well.\n\nThank you for bringing this straight to me; it is always best to go right to the top... But... Yes. The druids of the Cenarion Circle have known of the Wildkin for some time. That they are pets of Elune, and were chosen to guard the most sacred of places.\n\nSo while this isn't news, I definitely compliment you on your effort. Here, take this -- it is something that seems suitable for such a deed." } })
apply(4903, { "classic", "forever" }, { deDE = { progress = "<Kriegsherr Goretooth salutiert vor Euch.>", completion = "<Kriegsherr Goretooths mattgrüne Haut wird für einen Augenblick kreideweiß.>" }, enUS = { progress = "<Warlord Goretooth salutes.>", completion = "<Warlord Goretooth's dull green skin turns a pasty white for a brief moment.>" } })
apply(4904, { "classic", "forever" }, { deDE = { completion = "Ich danke Euch, {name}. Tief im Inneren wusste ich, dass sie ihren Weg zu mir zurückfinden würde. Sie hat mir von Eurem Mut berichtet und wie Ihr bei ihrer Flucht geholfen habt. Diese Gegenstände gehörten ihrem Bruder. Ich weiß, dass sie wollte, dass Ihr sie bekommt." }, enUS = { completion = "Thank you, {name}. Deep in my bones I knew that she would find her way back to me. She told me of your bravery and how you helped her escape. These items belonged to her brother. I know she would want you to have them." } })
apply(4906, { "classic", "forever" }, { deDE = { completion = "Vielen Dank für Eure Mühen, {name}. Möge Elune Euch beschützen und auf Eurem weiteren Weg leiten." }, enUS = { completion = "Thank you for all you have done, {name}. May Elune protect you and guide you on the path ahead." } })
apply(4907, { "classic", "forever" }, { deDE = { completion = "Felnok hatte Recht! Ich brauche wirklich Hilfe und dieses Mal... wird es wirklich gefährlich werden.\n\nSeid Ihr bereit?" }, enUS = { completion = "Felnok was right!  I do need your help again, and this time... it's going to be really dangerous.\n\nAre you ready??" } })
apply(4921, { "classic", "forever" }, { deDE = { completion = "Ich verstehe. Ich danke Euch, {class}." }, enUS = { completion = "I understand. Thank you, {class}." } })
apply(4941, { "classic", "forever" }, { deDE = { progress = "Seht Ihr nicht, dass ich nicht gestört werden will?", completion = "<Thrall scheint ob der Nachrichten, die Ihr bringt, bestürzt zu sein.>" }, enUS = { progress = "Can you not see that I must not be interrupted?", completion = "<Thrall appears dismayed by the news you bring.>" } })
apply(4961, { "classic", "forever" }, { deDE = { completion = "Sehr schön, {name}! Diese Lektion wird der Dämon nicht so schnell vergessen. Ihr habt bislang große Stärke und Können gezeigt. Jetzt solltet Ihr wohl mit Eurer gesäuberten Kugel zu Menara zurückkehren, um sie sinnvoll einzusetzen.\n\nViel Glück, {class}. Vielleicht kreuzen sich unsere Wege wieder einmal." }, enUS = { completion = "Nicely done, {name}!  You gave that demon a lesson he won't soon forget. You've shown great power and skill. Now I suppose it's time you return to Menara with your cleansed orb so you can put it to good use.\n\nGood luck, {class}. Perhaps our paths will cross again." } })
apply(4962, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Wofür habt Ihr Euch entschieden? Was soll es sein? Höllenbestie oder Teufelshund?\n\nEs ist eine persönliche Entscheidung, die Aufschluss über Eure Stärken und Schwächen bietet. Es kommt durchaus vor, dass {class} ihre bestehenden Fähigkeiten intensivieren, statt solche, die ihnen noch fehlen, aufzubauen. Manchmal ist die Taktik, einen Feind einfach kräftemäßig zu überwältigen, ebenso wirkungsvoll, wie danach zu trachten, ein ausgeglichenerer Zauberer zu werden.", completion = "Ah, der Geist eines Teufelshundes. Gut gemacht, {name}.\n\nWenn ich sowohl den Geist als auch die gesäuberte Kugel habe, werde ich beides miteinander für Euch verbinden... aber erst dann." }, enUS = { progress = "Yes, {name}? Have you chosen? Infernal or felhound?\n\nEach choice is personal and should reflect your strengths and weaknesses. It is not unheard of for a {class} to enhance themselves further instead of making up in areas they lack. Sometimes overpowering an enemy is just as strong a tactic than becoming a more balanced spell caster.", completion = "Ah, the spirit of a felhound. Well done, {name}.\n\nWhen I have both the spirit and the cleansed orb, I will merge the two for you, but not until then." } })
apply(4963, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Wofür habt Ihr Euch entschieden? Was soll es sein? Höllenbestie oder Teufelshund?\n\nEs ist eine persönliche Entscheidung, die Aufschluss über Eure Stärken und Schwächen bietet. Es kommt durchaus vor, dass {class} ihre bestehenden Fähigkeiten intensivieren, statt solche, die ihnen noch fehlen, aufzubauen. Manchmal ist die Taktik, einen Feind einfach kräftemäßig zu überwältigen, ebenso wirkungsvoll, wie danach zu trachten, ein ausgeglichenerer Zauberer zu werden.", completion = "Ah, der Geist einer Höllenbestie. Gut gemacht, {name}.\n\nWenn ich sowohl den Geist als auch die gesäuberte Kugel habe, werde ich beides miteinander für Euch verbinden... aber erst dann." }, enUS = { progress = "Yes, {name}? Have you chosen? Infernal or felhound?\n\nEach choice is personal and should reflect your strengths and weaknesses. It is not unheard of for a {class} to enhance themselves further instead of making up in areas they lack. Sometimes overpowering an enemy is just as strong a tactic than becoming a more balanced spell caster.", completion = "Ah, the spirit of an infernal. Well done, {name}.\n\nWhen I have both the spirit and the cleansed orb, I will merge the two for you, but not until then." } })
apply(4964, { "classic", "forever" }, { deDE = { completion = "Es ist vollbracht, {name}. Sagt mir, was Ihr lieber hättet: einen Stab, den Ihr mit beiden Händen führen müsstet, oder eine Kugel, sodass Ihr gleichzeitig noch einen Dolch oder ein Schwert als Waffe führen könnt.\n\nDass Ihr einen Teufelshund besiegt habt, war eine große Leistung. Ich bin mir sicher, dass dieser Gegenstand Euch in derZukunft gute Dienste leisten wird. Übt weiter fleißig Eure Künste, {name}. Ich brenne darauf, bald mehr von Euren Heldentaten zu hören." }, enUS = { completion = "It is done, {name}. Simply tell me which you'd prefer: a staff that would require you to use both hands, or an orb so you may use a dagger or sword as your weapon.\n\nTackling a felhound was a great feat on your part. I am sure your item will serve you well in the future. Continue to work hard in the arts, {name}. I will be awaiting details of your exploits." } })
apply(4965, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?" }, enUS = { completion = "Ah, you do seek something more... substantial. That I can help you if you truly are prepared.\n\nIt's a welcome change to see one of our kind seeking more power in forms other than just knowledge.\n\nSo, do you feel you're ready, {name}?" } })
apply(4966, { "classic", "forever" }, { deDE = { completion = "Danke für Eure Hilfe, {name}. Ohne Euch hätte ich sie nicht abhalten können." }, enUS = { completion = "Thank you for your help, {name}. I couldn't have held them off without you." } })
apply(4967, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?" }, enUS = { completion = "Ah, you do seek something more... substantial. That I can help you if you truly are prepared.\n\nIt's a welcome change to see one of our kind seeking more power in forms other than just knowledge.\n\nSo, do you feel you're ready, {name}?" } })
apply(4968, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?" }, enUS = { completion = "Ah, you do seek something more... substantial. That I can help you if you truly are prepared.\n\nIt's a welcome change to see one of our kind seeking more power in forms other than just knowledge.\n\nSo, do you feel you're ready, {name}?" } })
apply(4969, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr sucht nach etwas... Greifbarerem. Da kann ich Euch behilflich sein, wenn Ihr wirklich darauf vorbereitet seid.\n\nEs ist eine willkommene Abwechslung zu sehen, dass jemand unserer Art nach mehr Macht strebt statt nur nach Wissen.\n\nAlso, denkt Ihr, Ihr seid bereit, {name}?" }, enUS = { completion = "Ah, you do seek something more... substantial. I can help you if you truly are prepared.\n\nIt's a welcome change to see one of our kind seeking more power in forms other than just knowledge.\n\nSo, do you feel you're ready, {name}?" } })
apply(4970, { "classic", "forever" }, { deDE = { progress = "Disziplin und Bestimmtheit sind Eure Ziele. Ich werde Euch häufig bitten, einfache Aufgaben zu erledigen; Ihr müsst sie jeweils erfüllen, so gut es Euch möglich ist.", completion = "Danke, dass Ihr mir geholfen habt, {name}. Meine Meinung von Euch wächst mit der Zeit." }, enUS = { progress = "Discipline and determination are your goals. I may ask you to do a simple task many times; you must perform to the best of your ability each time.", completion = "Thank you for assisting me, {name}. My opinion of you grows as time passes." } })
apply(4971, { "classic", "forever" }, { deDE = { progress = "Temporale Parasiten sind eine Landplage, die immer dann auftritt, wenn sich jemand am Zeitablauf zu schaffen macht. Ich spüre, dass es eine Menge davon gibt, und das beunruhigt mich.\n\nRottet so viele aus, wie Ihr finden könnt. Das wird mir helfen, die sich stetig verschlechternde temporale Lage wieder unter Kontrolle zu bringen. Ich kann es spüren, sobald Ihr Erfolg hattet.", completion = "Es scheint jetzt leichter zu sein, die Zeit wieder zu korrigieren, danke, {name}. Ihr mögt vielleicht nicht ganz verstehen, welche Konsequenzen ein aus den Fugen geratener Zeitablauf, eine gestörte Zeitlinie, haben kann, aber ich weiß es zu schätzen, dass Ihr versteht, wie dringlich es ist, dem Einhalt zu gebieten, was ich mehr und mehr für eine von der Geißel verursachte Bösartigkeit halte.\n\nEs ist wohl angebracht, dass ich Euch für Eure Hilfe belohne, sterbliches Wesen. Die größten Aufgaben stehen Euch noch bevor und ein kleines Schmuckstück als Belohnung wird Euer Schicksal bestimmt nicht beeinflussen. Eure beständige Unterstützung jedoch ist etwas, das für mich und den Drachenschwarm sehr nützlich sein könnte..." }, enUS = { progress = "Temporal parasites are a common malady present wherever the flow of time has been tampered with.  I sense that many are present, and this is disturbing.\n\nRooting out whatever ones you can find will help me be able to take a better hold on the deteriorating temporal situation here.  I will be able to sense when this has been achieved.", completion = "Time feels easier to mend now, thank you {name}.  While you might not understand fully the consequences of a fractured timeline, I appreciate that you understand the urgency of countering what I suspect more and more to be a Scourge-driven malfeasance.\n\nI see no harm in rewarding you for your assistance, mortal.  Your greatest feats are to come, and the awarding of a bauble will certainly not alter your future destiny.  Your continued aid, however, is something that I and the dragonflight could use..." } })
apply(4972, { "classic", "forever" }, { deDE = { progress = "Die Zeitobjekte sind einfache Geräte. Es handelt sich hauptsächlich um Uhren, deren Zeiger stehen blieben, als die Seuche das erste Mal über Andorhal hereinbrach.\n\nDie Zeit bleibt niemals stehen und die Uhren, die Ihr mir bringt, kehren mit unfehlbarer Sicherheit immer wieder zu ihrem Ursprungsort zurück... das heißt, solange die Störungen hier andauern.", completion = "Genau das, was ich brauche, {name}. Danke.\n\nErlaubt mir, Euch hiermit angemessen zu belohnen. Ihr fragt Euch vielleicht jetzt, was Ihr mit einem solchen Gerät anfangen sollt. Vielleicht wisst Ihr nicht einmal, worum es sich dabei genau handelt. Ich kann Euch leider nicht sagen, wann genau es Euch nützlich sein wird. Ihr müsst nur wissen, dass es irgendwann in der Zukunft äußerst nützlich und praktisch sein wird, wenn Ihr es benutzt. Ob Ihr es bis dahin behaltet oder nicht ... das bleibt allein Euch überlassen." }, enUS = { progress = "The time trinkets I seek are simple devices.  They are watches mainly, and their hands are trapped forever when the plague first ravaged Andorhal.\n\nTime is never ending, and the watches you bring to me will invariably find themselves counted out back to their homes... that is, so long as the disturbances continue here.", completion = "These are exactly what I need, {name}.  Thank you.\n\nAllow me to suitably reward you with this.  You may not understand what you would need with such a device.  You might not even know quite what it really is.  Alas, I cannot tell you when you will find it most useful; just know that at some point in the future, you may find this item to have extreme utility and function when consumed.  Whether or not you choose to hold on to it until then... this, my friend, is up to you." } })
apply(4973, { "classic", "forever" }, { deDE = { progress = "Die Uhren von Andorhal, ähnlich wie die große Uhr in der Ruine des Rathauses, sind sämtlich um drei Uhr stehen geblieben. Genau zu diesem Zeitpunkt hatte die Seuche die Stadt zum ersten Mal mit voller Wucht getroffen, sich ausgebreitet und jegliches Leben darin erstickt.\n\nSo sehr wir alle es auch bedauern, was an diesem Tag geschah, so sehr hat es doch auch den Zeitfluss geprägt, wie Ihr Sterblichen ihn heute empfindet. Der bronzene Drachenschwarm darf nicht nachlassen, die Zeitlinie zu schützen!", completion = "Habt abermals Dank für Eure Unterstützung. Bitte nehmt dieses Geschenk. Ihr mögt zwar immer noch nicht wissen, wann Ihr einen solchen Gegenstand benutzen könnt, aber vielleicht wird Euch irgendwann der Lauf der Zeit enthüllen, was Euch beschieden ist. Man könnte sagen, ich habe gesehen, dass es sich so ereignen wird, {name}." }, enUS = { progress = "The watches of Andorhal, much like the large clock on the ruins of the town hall, all are frozen in time at three o'clock.  This was when the full effects of the plague first spread out over the city, choking the life out of it.\n\nAs much as we all may regret what happened that day, it has shaped the flow of time as you mortals perceive it.  The bronze dragonflight must persevere in protecting the timeline!", completion = "Again, I think you for your assistance.  Please accept this gift.  While you still may not know when to use such an item, perhaps in the future the path of time will reveal its true intentions to you.  You could say that I've seen as such happening to you, {name}." } })
